INSERT INTO easa_subjects (module_id, code, title, sort_order) VALUES
  (6, 'M06.12', 'Exam Question Bank', 12)
    INSERT INTO questions (subject_id, text, options, licence_types) VALUES
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of the following is susceptible to the ingress of moisture?', '[{"id": "a", "text": "Kevlar.", "correct": true}, {"id": "b", "text": "Carbon fibre.", "correct": false}, {"id": "c", "text": "Glass fibre.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When drilling stainless steel, use a', '[{"id": "a", "text": "drill ground to 120 °, slow cutting speed.", "correct": true}, {"id": "b", "text": "drill ground to 90 °, fast cutting speed.", "correct": false}, {"id": "c", "text": "drill ground to 90 °, slow cutting speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How is a material galvanised?', '[{"id": "a", "text": "Sprayed with nickel solution.", "correct": false}, {"id": "b", "text": "Packed in a drum containing zinc dust and heated.", "correct": false}, {"id": "c", "text": "Dipped in a bath of molten zinc.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What temperature would steel be tempered at?', '[{"id": "a", "text": "At the annealing temperature.", "correct": false}, {"id": "b", "text": "Above the annealing temperature.", "correct": false}, {"id": "c", "text": "Below the annealing temperature.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Tempering steel gives', '[{"id": "a", "text": "greater brittleness.", "correct": false}, {"id": "b", "text": "greater hardness.", "correct": false}, {"id": "c", "text": "relief of internal stress after hardening.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The addition of chromium to steel will produce', '[{"id": "a", "text": "toughness.", "correct": false}, {"id": "b", "text": "hardness.", "correct": true}, {"id": "c", "text": "ductility.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Chromium added to plain carbon steel', '[{"id": "a", "text": "increases its resistance to corrosion.", "correct": true}, {"id": "b", "text": "turns it into a non-ferrous alloy.", "correct": false}, {"id": "c", "text": "makes the metal softer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The purpose of case hardening is to', '[{"id": "a", "text": "produce a hard case over a tough core.", "correct": true}, {"id": "b", "text": "reduce the carbon in the steel.", "correct": false}, {"id": "c", "text": "introduce carbon into the steel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'At normal temperatures HC steel is harder because', '[{"id": "a", "text": "it has more austenite.", "correct": false}, {"id": "b", "text": "of the percentage of carbon in the grain structure.", "correct": true}, {"id": "c", "text": "it has less austenite.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Nitriding is', '[{"id": "a", "text": "tempering.", "correct": false}, {"id": "b", "text": "anodising.", "correct": false}, {"id": "c", "text": "case hardening.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Medium carbon steels have a carbon content of', '[{"id": "a", "text": "0.3 - 0.5 %.", "correct": true}, {"id": "b", "text": "0.5 - 0.8 %.", "correct": false}, {"id": "c", "text": "0.8 - 1.05 %.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A ferrous metal contains', '[{"id": "a", "text": "aluminium.", "correct": false}, {"id": "b", "text": "iron.", "correct": true}, {"id": "c", "text": "magnesium.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'With respect to ferrous metals which of the following is true?', '[{"id": "a", "text": "Iron is not an element of ferrous metals.", "correct": false}, {"id": "b", "text": "Iron is a main element and most ferrous metals are magnetic.", "correct": true}, {"id": "c", "text": "Iron is a main element and ferrous metals are not magnetic.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The annealing process on steel is required sometimes as it', '[{"id": "a", "text": "provides a corrosion resistant layer that prevents oxidation.", "correct": false}, {"id": "b", "text": "allows the material a greater stress per unit area.", "correct": false}, {"id": "c", "text": "relieves internal stress suffered after engineering processes.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Cobalt steel tested on the Brinell test would have a BHN number between', '[{"id": "a", "text": "100 to 175.", "correct": false}, {"id": "b", "text": "300 to 400.", "correct": false}, {"id": "c", "text": "600 to 700.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'If a material is found to be in the tertiary phase of creep, the following procedure should be implemented:', '[{"id": "a", "text": "The component should undergo a dye penetrant check and be condition monitored.", "correct": false}, {"id": "b", "text": "The crack should be stop drilled and condition monitoring applied.", "correct": false}, {"id": "c", "text": "The component should be replaced immediately.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is used for marking out steels?', '[{"id": "a", "text": "Engineers blue.", "correct": true}, {"id": "b", "text": "Wax crayon.", "correct": false}, {"id": "c", "text": "Copper sulphate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Phosphating of steels is carried out by immersing the steel into a solution of', '[{"id": "a", "text": "phosphoric acid and metal phosphates.", "correct": true}, {"id": "b", "text": "nitric acid and sulphur.", "correct": false}, {"id": "c", "text": "metal phosphates and sulphuric acid.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Tempering entails', '[{"id": "a", "text": "heating under the UCP and slow cooling.", "correct": true}, {"id": "b", "text": "heating over the UCP and fast cooling.", "correct": false}, {"id": "c", "text": "heating over the UCP and slow cooling.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Austenitic stainless steels are', '[{"id": "a", "text": "magnetic.", "correct": false}, {"id": "b", "text": "non-magnetic.", "correct": true}, {"id": "c", "text": "hardened by heat treatment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The formation of steel depends upon', '[{"id": "a", "text": "the formation of pearlite into austenite.", "correct": false}, {"id": "b", "text": "the formation of austenite into pearlite.", "correct": true}, {"id": "c", "text": "the presence of pearlite in the structure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How is residual magnetism removed after an NDT examination?', '[{"id": "a", "text": "EMI.", "correct": false}, {"id": "b", "text": "EMC.", "correct": false}, {"id": "c", "text": "Degaussing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The hardness of steel depends upon', '[{"id": "a", "text": "formation of pearlite into austenite.", "correct": false}, {"id": "b", "text": "formation of cementite.", "correct": true}, {"id": "c", "text": "the iron austenite grain structure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The difference between annealing and normalizing is', '[{"id": "a", "text": "both are heated above the UCT, cool slowly to anneal, cool in air to normalize.", "correct": true}, {"id": "b", "text": "both are heated below the UCT, cool in air to anneal, cool slowly to normalize.", "correct": false}, {"id": "c", "text": "both are heated above the UCT, cool in air to anneal, cool slowly to normalize.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Normalizing of steel is done to', '[{"id": "a", "text": "remove residual stress of the manufacturing process.", "correct": true}, {"id": "b", "text": "make steel softer.", "correct": false}, {"id": "c", "text": "restore the fatigue life of steel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When normalising, the material is', '[{"id": "a", "text": "quenched immediately.", "correct": false}, {"id": "b", "text": "left to cool at room temperature.", "correct": true}, {"id": "c", "text": "cooled slowly.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Cast iron is', '[{"id": "a", "text": "very malleable.", "correct": false}, {"id": "b", "text": "tough.", "correct": false}, {"id": "c", "text": "heavy and brittle.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Case hardening can be carried out on', '[{"id": "a", "text": "titanium.", "correct": false}, {"id": "b", "text": "any ferrous metal.", "correct": true}, {"id": "c", "text": "duralumin.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Exhaust systems are usually made from stainless steel which is susceptible to', '[{"id": "a", "text": "surface corrosion.", "correct": false}, {"id": "b", "text": "filiform corrosion.", "correct": false}, {"id": "c", "text": "intergranular corrosion.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When metal is first heated slightly above its critical temperature and then cooled rapidly it is common that the metal will increase in', '[{"id": "a", "text": "brittleness.", "correct": false}, {"id": "b", "text": "hardness.", "correct": false}, {"id": "c", "text": "both of the above.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Steel is tempered', '[{"id": "a", "text": "after hardening.", "correct": true}, {"id": "b", "text": "before hardening.", "correct": false}, {"id": "c", "text": "to increase hardening.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'If a steel component is operated below the fatigue limit, the fatigue life is', '[{"id": "a", "text": "finite.", "correct": false}, {"id": "b", "text": "infinite.", "correct": true}, {"id": "c", "text": "dependent on its proof stress.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A low carbon steel would normally be case hardened using', '[{"id": "a", "text": "the nitriding process.", "correct": false}, {"id": "b", "text": "flame or induction hardening.", "correct": false}, {"id": "c", "text": "pack or gas carburising.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'After a product has been manufactured and all heat treatment has been carried out the stress remaining if any is termed as', '[{"id": "a", "text": "working stress.", "correct": false}, {"id": "b", "text": "residual stress.", "correct": true}, {"id": "c", "text": "applied stress.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Annealing steels', '[{"id": "a", "text": "toughens the metal.", "correct": false}, {"id": "b", "text": "makes the metal malleable.", "correct": true}, {"id": "c", "text": "makes the metal brittle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Tempering of hardened steel is carried out to', '[{"id": "a", "text": "retain surface hardness, but soften the core.", "correct": false}, {"id": "b", "text": "retain core hardness, but soften the surface.", "correct": false}, {"id": "c", "text": "significantly reduce the brittleness without suffering a major drop in its strength.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'High speed steel relies heavily on the following metallic element for its ability to cut other metals, even when it is heated to a dull colour', '[{"id": "a", "text": "Tungsten.", "correct": true}, {"id": "b", "text": "Nickel.", "correct": false}, {"id": "c", "text": "Vanadium.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When a low carbon steel bolt is stretched beyond its elastic limit without breaking, it will', '[{"id": "a", "text": "deform temporarily.", "correct": false}, {"id": "b", "text": "become more ductile.", "correct": false}, {"id": "c", "text": "deform permanently.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), '1% Nickel, 1% Carbon, steel is widely used for', '[{"id": "a", "text": "exhaust valves.", "correct": false}, {"id": "b", "text": "ball and roller bearings.", "correct": true}, {"id": "c", "text": "high tensile steel bolts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Fatigue failure may be defined as', '[{"id": "a", "text": "failure caused by stress in excess of the material U.T.S.", "correct": false}, {"id": "b", "text": "failure due to impact.", "correct": false}, {"id": "c", "text": "reduction in strength due to alternating loads.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Normalising steels', '[{"id": "a", "text": "increases toughness.", "correct": false}, {"id": "b", "text": "increases the hardness.", "correct": false}, {"id": "c", "text": "relieves the stresses.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Cast iron is', '[{"id": "a", "text": "tough.", "correct": false}, {"id": "b", "text": "heavy and brittle.", "correct": true}, {"id": "c", "text": "very malleable.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Austenitic steel is produced when the material is heated to', '[{"id": "a", "text": "above the Upper Critical Point.", "correct": true}, {"id": "b", "text": "above the Lower Critical Point.", "correct": false}, {"id": "c", "text": "below the Upper Critical Point.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Steel is produced by refining pig iron where air/oxygen is blown through the molten material to remove', '[{"id": "a", "text": "carbon.", "correct": true}, {"id": "b", "text": "oxides.", "correct": false}, {"id": "c", "text": "sulphur.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'During a Rockwell Hardness test, what dimension is measured?', '[{"id": "a", "text": "The diameter of the indent.", "correct": false}, {"id": "b", "text": "The depth of the indent.", "correct": true}, {"id": "c", "text": "The diameter and depth of the indent.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What does the 0 in 2024-T3 mean?', '[{"id": "a", "text": "The percentage of impurities in the alloy.", "correct": false}, {"id": "b", "text": "The alloy has not been modified.", "correct": true}, {"id": "c", "text": "The alloy has been modified.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In most aircraft hydraulic systems, two-piece tube connectors consisting of a sleeve and a nut are used when a tubing flare is required. The use of this type of connector eliminates', '[{"id": "a", "text": "the flaring operation prior to assembly.", "correct": false}, {"id": "b", "text": "the possibility of reducing the flare thickness by wiping or ironing during the tightening process.", "correct": true}, {"id": "c", "text": "wrench damage to the tubing during the tightening process.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In the tensile strength test', '[{"id": "a", "text": "the material is pulled to limit of elasticity.", "correct": false}, {"id": "b", "text": "the material is pulled until it breaks.", "correct": true}, {"id": "c", "text": "the material is pulled until it reaches its UTS.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Impact resistance measures the', '[{"id": "a", "text": "material toughness.", "correct": true}, {"id": "b", "text": "material hardness.", "correct": false}, {"id": "c", "text": "material ductility.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Specified time of contact between the indentor and test piece in a Vickers or Brinell hardness test is', '[{"id": "a", "text": "20 seconds.", "correct": false}, {"id": "b", "text": "10 seconds.", "correct": false}, {"id": "c", "text": "15 seconds.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In an Izod impact test the striking energy of the striker is approximately', '[{"id": "a", "text": "150 J.", "correct": false}, {"id": "b", "text": "163 J.", "correct": true}, {"id": "c", "text": "300 J.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The Charpy test measures', '[{"id": "a", "text": "strain.", "correct": false}, {"id": "b", "text": "impact energy.", "correct": true}, {"id": "c", "text": "Young''s modulus.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The ''Fatigue limit'' for steel is generally in the region of, compared to the static U.T.S', '[{"id": "a", "text": "40%-60%.", "correct": true}, {"id": "b", "text": "60%-80%.", "correct": false}, {"id": "c", "text": "20%-40%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The ability of mild steel to accept more load after the yield point is reached is due to', '[{"id": "a", "text": "necking.", "correct": false}, {"id": "b", "text": "strain hardening.", "correct": true}, {"id": "c", "text": "plasticisation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is a Rockwell tester used for?', '[{"id": "a", "text": "Hardness Testing.", "correct": true}, {"id": "b", "text": "Tensile Testing.", "correct": false}, {"id": "c", "text": "Fatigue Testing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What type of test involves using a weighted pendulum to strike a material until fracture?', '[{"id": "a", "text": "Hardness Test.", "correct": false}, {"id": "b", "text": "Impact Resistance Test.", "correct": true}, {"id": "c", "text": "Fatigue Testing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of the following are all hardness testing machines?', '[{"id": "a", "text": "Rockwell, Brinell and Izod.", "correct": false}, {"id": "b", "text": "Rockwell, Vickers and Izod.", "correct": false}, {"id": "c", "text": "Rockwell, Brinell and Vickers.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The most suitable mixture for a salt bath operation is', '[{"id": "a", "text": "50% sodium nitrate and 50% potassium nitrate.", "correct": true}, {"id": "b", "text": "90% sodium nitrate and 10% potassium nitrate.", "correct": false}, {"id": "c", "text": "70% sodium chlorate and 30% sodium nitrate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How many times can clad alloy be heat treated?', '[{"id": "a", "text": "Once only.", "correct": false}, {"id": "b", "text": "3 times.", "correct": true}, {"id": "c", "text": "as many times as required.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The symbol ''W'' on a material indicates', '[{"id": "a", "text": "it is for use on aircraft mainplanes only.", "correct": false}, {"id": "b", "text": "it has been solution treated and will respond effectively to precipitation treatment.", "correct": true}, {"id": "c", "text": "it is for workshop use only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'For a particular metal material, what conditions are best to minimise creep?', '[{"id": "a", "text": "Low stress, low temperature.", "correct": true}, {"id": "b", "text": "Low stress, high temperature.", "correct": false}, {"id": "c", "text": "High stress, low temperature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the effect of precipitation heat treatment on aluminium?', '[{"id": "a", "text": "It speeds up age hardening process.", "correct": true}, {"id": "b", "text": "It delays the age hardening process.", "correct": false}, {"id": "c", "text": "It softens the material to allow it to be worked.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Aluminium exposed to air will', '[{"id": "a", "text": "oxidise and become weaker.", "correct": false}, {"id": "b", "text": "oxidise and become electrically insulated.", "correct": true}, {"id": "c", "text": "oxidise and become stronger.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What care should you take with 2024-T3? [see note]', '[{"id": "a", "text": "Do not scratch or make nicks in it.", "correct": true}, {"id": "b", "text": "Do not bend at sharp angles.", "correct": false}, {"id": "c", "text": "Do not remove the surface of the sheet metal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The composition of soft solder is', '[{"id": "a", "text": "tin and lead.", "correct": true}, {"id": "b", "text": "tin, lead and silver.", "correct": false}, {"id": "c", "text": "tin, lead, silver and antimony.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'If aluminium alloy is not quenched within the minimum time allowed after heat treatment is it will be', '[{"id": "a", "text": "subject to corrosion.", "correct": true}, {"id": "b", "text": "malleable.", "correct": false}, {"id": "c", "text": "brittle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Anodizing protects alloy metal from corrosion and does what else?', '[{"id": "a", "text": "Seals the surface from moisture.", "correct": false}, {"id": "b", "text": "Makes a good surface for paint to adhere to.", "correct": true}, {"id": "c", "text": "Makes the surface alkaline.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'If caustic soda turns a material black what is it?', '[{"id": "a", "text": "Aluminium alloy.", "correct": true}, {"id": "b", "text": "Alclad.", "correct": false}, {"id": "c", "text": "Aluminium.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What chemical is used to identify aluminium alloys?', '[{"id": "a", "text": "Caustic soda.", "correct": true}, {"id": "b", "text": "Copper sulphate.", "correct": false}, {"id": "c", "text": "Nitric acid.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Pure aluminium is', '[{"id": "a", "text": "highly resistant to corrosion.", "correct": true}, {"id": "b", "text": "not resistant to corrosion.", "correct": false}, {"id": "c", "text": "reasonably resistant to corrosion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Precipitation treating makes the metal', '[{"id": "a", "text": "softer and more ductile.", "correct": false}, {"id": "b", "text": "less strong and hard.", "correct": false}, {"id": "c", "text": "harder, stronger and less ductile.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A material has the code 2024-T36. Which part of the code indicates the heat treatment condition of the material?', '[{"id": "a", "text": "T36.", "correct": true}, {"id": "b", "text": "20.", "correct": false}, {"id": "c", "text": "24.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Aluminium alloyed primarily with magnesium is numbered', '[{"id": "a", "text": "2025.", "correct": false}, {"id": "b", "text": "5025.", "correct": true}, {"id": "c", "text": "1025.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Heat treatment is shown on a British aluminium alloy by a', '[{"id": "a", "text": "letter and number code.", "correct": false}, {"id": "b", "text": "number code.", "correct": false}, {"id": "c", "text": "letter code.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Non heat treatable materials', '[{"id": "a", "text": "cannot be hardened.", "correct": false}, {"id": "b", "text": "can be hardened by strain hardening or cold working.", "correct": true}, {"id": "c", "text": "can be hardened by annealing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of the following metals is an aluminium silicon alloy used mainly for casting?', '[{"id": "a", "text": "Alclad.", "correct": false}, {"id": "b", "text": "Aldrey.", "correct": false}, {"id": "c", "text": "Alpax.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Aircraft skin is joggled to [see note]', '[{"id": "a", "text": "provide smooth airflow at faying surfaces.", "correct": true}, {"id": "b", "text": "make a frame lighter but stronger.", "correct": false}, {"id": "c", "text": "conform to the aircraft contour.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The British system of heat treatment codes is', '[{"id": "a", "text": "a series of letters.", "correct": true}, {"id": "b", "text": "numbers and letters.", "correct": false}, {"id": "c", "text": "a series of numbers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In a sheet metal store, one sheet of aluminium alloy is marked L162 (sheet 1) and a different sheet is marked L172 (sheet 2). Which of the following is true?', '[{"id": "a", "text": "Sheet one has a shinier surface than sheet 2.", "correct": false}, {"id": "b", "text": "Sheet one is more ductile than sheet 2.", "correct": true}, {"id": "c", "text": "Sheet two is of a thicker gauge than sheet 1.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Cold working of a material is used to reduce', '[{"id": "a", "text": "material hardness.", "correct": false}, {"id": "b", "text": "fatigue.", "correct": true}, {"id": "c", "text": "wear of manufacturing tools.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Sheet metal should be stored', '[{"id": "a", "text": "above 25 degrees centigrade.", "correct": false}, {"id": "b", "text": "on its edge in racks to prevent scratching.", "correct": true}, {"id": "c", "text": "stacked flat to prevent bending of sheets.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Clad aluminium alloy (alclad) has a pure aluminium coating of', '[{"id": "a", "text": "0.002.", "correct": false}, {"id": "b", "text": "1% of alloy thickness.", "correct": false}, {"id": "c", "text": "5% of alloy thickness.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The main metal in Monel is', '[{"id": "a", "text": "aluminium.", "correct": false}, {"id": "b", "text": "nickel.", "correct": true}, {"id": "c", "text": "stainless steel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A tube complying to BS T51 is', '[{"id": "a", "text": "tungum.", "correct": true}, {"id": "b", "text": "HTS tube.", "correct": false}, {"id": "c", "text": "high pressure seamless copper tube.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Why is nickel chromium used in many exhaust systems?', '[{"id": "a", "text": "Corrosion resistant and high heat conductivity.", "correct": false}, {"id": "b", "text": "Lightweight and flexible.", "correct": false}, {"id": "c", "text": "Corrosion resistant and low expansion coefficient.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Titanium alloys', '[{"id": "a", "text": "are cheap to manufacture.", "correct": false}, {"id": "b", "text": "have a high strength to weight ratio.", "correct": true}, {"id": "c", "text": "are corrosion resistant but heavy.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which part of the 2017-T36 aluminium alloy designation indicates the primary alloying agent used in its manufacture?', '[{"id": "a", "text": "20.", "correct": false}, {"id": "b", "text": "2.", "correct": true}, {"id": "c", "text": "17.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Clad aluminium alloys are used in aircraft because they', '[{"id": "a", "text": "are harder wearing than unclad aluminium alloys.", "correct": false}, {"id": "b", "text": "are less subject to corrosion than uncoated aluminium alloys.", "correct": true}, {"id": "c", "text": "are stronger than unclad aluminium alloys.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Non heat treatable aluminium alloys', '[{"id": "a", "text": "can be hardened by strain hardening.", "correct": true}, {"id": "b", "text": "cannot be softened.", "correct": false}, {"id": "c", "text": "cannot be hardened.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Solution treatment after manufacturers have performed it once can be carried out a further', '[{"id": "a", "text": "1 time.", "correct": false}, {"id": "b", "text": "2 times.", "correct": true}, {"id": "c", "text": "3 times.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Following solution treatment aluminium alloy can be placed into service', '[{"id": "a", "text": "after 5 days.", "correct": true}, {"id": "b", "text": "straight away.", "correct": false}, {"id": "c", "text": "after 24 hours.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The time between removal from heat treatment furnace and quenching must be not more than. [see note]', '[{"id": "a", "text": "3 seconds.", "correct": false}, {"id": "b", "text": "10 seconds.", "correct": true}, {"id": "c", "text": "7 seconds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When buffing surface of Aluminium Alloy, what material are you removing?', '[{"id": "a", "text": "Oxide layer.", "correct": true}, {"id": "b", "text": "Aluminium.", "correct": false}, {"id": "c", "text": "Alloy.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Why is clad alloy preferred to pure Aluminium?', '[{"id": "a", "text": "Less brittle.", "correct": false}, {"id": "b", "text": "More ductile.", "correct": false}, {"id": "c", "text": "Tougher.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Why are aluminium alloys used on aircraft, instead of pure aluminium?', '[{"id": "a", "text": "Stronger.", "correct": true}, {"id": "b", "text": "Corrosion resistant.", "correct": false}, {"id": "c", "text": "Lighter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The magnesium alloys used in aircraft can be recognized by', '[{"id": "a", "text": "shiny surface due to chromium plated on the surface.", "correct": false}, {"id": "b", "text": "yellowish surface due to protective treatment.", "correct": true}, {"id": "c", "text": "silver surface due to protective coating.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Age hardening of aluminium is', '[{"id": "a", "text": "never carried out.", "correct": false}, {"id": "b", "text": "a gradual hardening over a period of time.", "correct": true}, {"id": "c", "text": "not necessary.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Alclad is', '[{"id": "a", "text": "aluminium with duralumin cladding.", "correct": false}, {"id": "b", "text": "duralumin with aluminium coating.", "correct": true}, {"id": "c", "text": "duralumin with magnesium cladding.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The oxide film on the surface of aluminium is [see note]', '[{"id": "a", "text": "hard and porous.", "correct": false}, {"id": "b", "text": "porous.", "correct": false}, {"id": "c", "text": "non porous.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The process of forming a pure layer of aluminium over an aluminium alloy is', '[{"id": "a", "text": "metalizing.", "correct": false}, {"id": "b", "text": "cladding.", "correct": true}, {"id": "c", "text": "electroplating.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Titanium can be identified by placing it on a grinding wheel and looking for', '[{"id": "a", "text": "Red Sparks.", "correct": false}, {"id": "b", "text": "Yellow Sparks.", "correct": false}, {"id": "c", "text": "White Sparks.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The critical process of heat treatment is', '[{"id": "a", "text": "temperature, method of heating and cooling.", "correct": true}, {"id": "b", "text": "temperature and method of heating only.", "correct": false}, {"id": "c", "text": "method of heating only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Re-treatment of aluminium alloys can be performed by', '[{"id": "a", "text": "Alocrom treatment.", "correct": false}, {"id": "b", "text": "brushing on phosphate treatment followed by paint.", "correct": false}, {"id": "c", "text": "selenious acid treatment.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is generally true for titanium alloy?', '[{"id": "a", "text": "It is stronger than the aluminium.", "correct": true}, {"id": "b", "text": "It is stronger than the steel.", "correct": false}, {"id": "c", "text": "It has lower density than magnesium.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Malleable materials are', '[{"id": "a", "text": "easy to forge.", "correct": true}, {"id": "b", "text": "easy to cast.", "correct": false}, {"id": "c", "text": "highly ductile.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'If a material has to undergo deep cold forming operation, the essential property would be', '[{"id": "a", "text": "ductility.", "correct": true}, {"id": "b", "text": "malleability.", "correct": false}, {"id": "c", "text": "elasticity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The metal which must not be heated in a salt bath is', '[{"id": "a", "text": "magnesium alloy.", "correct": true}, {"id": "b", "text": "duralumin.", "correct": false}, {"id": "c", "text": "rivets made of alclad.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The colour code on sheet metal indicates', '[{"id": "a", "text": "only the specification of the material.", "correct": true}, {"id": "b", "text": "the spec and gauge of the material.", "correct": false}, {"id": "c", "text": "that the material is from an approved source.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When two or more metallic materials are fused together, the combination is known as', '[{"id": "a", "text": "a composite material.", "correct": false}, {"id": "b", "text": "a thermosetting compound.", "correct": false}, {"id": "c", "text": "an alloy.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Malleable materials are normally', '[{"id": "a", "text": "also highly ductile.", "correct": true}, {"id": "b", "text": "easy to cast.", "correct": false}, {"id": "c", "text": "easily forged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The common bonding material for Tungsten Carbide is', '[{"id": "a", "text": "Invar.", "correct": false}, {"id": "b", "text": "Cobalt.", "correct": true}, {"id": "c", "text": "Silicon.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Grain size will effect the mechanical properties of metal. Which of the following is true?', '[{"id": "a", "text": "Large grain size is attributed to slow cooling rates and will give less tensile strength.", "correct": true}, {"id": "b", "text": "Materials with large grain size are more prone to creep.", "correct": false}, {"id": "c", "text": "Small grain size is normally attributed to rapid cooling rates and will give less tensile strength.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The cracking of structural members under repeated stress lower than the ultimate tensile load is known as', '[{"id": "a", "text": "creep.", "correct": false}, {"id": "b", "text": "fatigue failure.", "correct": true}, {"id": "c", "text": "stress reversal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The cracking of structural members under repeated stress lower than the ultimate tensile load is known as', '[{"id": "a", "text": "creep.", "correct": false}, {"id": "b", "text": "fatigue failure.", "correct": true}, {"id": "c", "text": "stress reversal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A sheet of metal is designated 2024-T4. The code tells us that the material is a copper based aluminium alloy', '[{"id": "a", "text": "annealed and Naturally aged.", "correct": false}, {"id": "b", "text": "solution treated and naturally aged.", "correct": true}, {"id": "c", "text": "solution treated and artificially aged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A metal is coded 1285 using the IADS coding method. This means the metal is', '[{"id": "a", "text": "85% pure aluminium.", "correct": false}, {"id": "b", "text": "99.85% pure aluminium.", "correct": true}, {"id": "c", "text": "a copper based aluminium alloy i.e. duralumin.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A material containing approximately 66% nickel and 33% copper is known as', '[{"id": "a", "text": "Nimonic.", "correct": false}, {"id": "b", "text": "Monel metal.", "correct": true}, {"id": "c", "text": "Invar.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Monel metal consists of approximately', '[{"id": "a", "text": "66% Copper and 33% Nickel.", "correct": false}, {"id": "b", "text": "66% Chromium and 33% Copper.", "correct": false}, {"id": "c", "text": "66% Nickel and 33% Copper.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Silver solder is composed of the materials', '[{"id": "a", "text": "Copper, Tin and Silver.", "correct": false}, {"id": "b", "text": "Zinc, Lead and Silver.", "correct": false}, {"id": "c", "text": "Copper, Zinc and Silver.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is fatigue?', '[{"id": "a", "text": "Cyclic stressing of a part.", "correct": true}, {"id": "b", "text": "Failure of a component due to corrosion.", "correct": false}, {"id": "c", "text": "Constant stressing of a part.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Why is stop drilling carried out at the end of a crack?', '[{"id": "a", "text": "To change the direction of the crack.", "correct": false}, {"id": "b", "text": "To stop the crack from propagating.", "correct": true}, {"id": "c", "text": "To increase the stress concentration at the crack end.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Annealing of aluminium', '[{"id": "a", "text": "increases the tensile strength.", "correct": false}, {"id": "b", "text": "makes the material brittle.", "correct": false}, {"id": "c", "text": "removes stresses caused by forming.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The impact testing technique is used on a material to test for', '[{"id": "a", "text": "hardness.", "correct": false}, {"id": "b", "text": "toughness.", "correct": true}, {"id": "c", "text": "shear strain.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'An S-N curve is useful in the design evaluation process for testing', '[{"id": "a", "text": "fatigue life.", "correct": true}, {"id": "b", "text": "shear force.", "correct": false}, {"id": "c", "text": "tension.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is a fusible material?', '[{"id": "a", "text": "The ability of two dissimilar metals to melt together.", "correct": false}, {"id": "b", "text": "The ability of a metal to melt.", "correct": true}, {"id": "c", "text": "The ability of a metal to be welded.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Brittleness is', '[{"id": "a", "text": "the property to resist wear.", "correct": false}, {"id": "b", "text": "the property to not deform before cracking.", "correct": true}, {"id": "c", "text": "the property to resist deformation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The proof stress of a material is the stress at which', '[{"id": "a", "text": "the material yields.", "correct": false}, {"id": "b", "text": "small amount of permanent set takes place.", "correct": true}, {"id": "c", "text": "necking of the material begins.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The S.I. unit for strain is', '[{"id": "a", "text": "N/mm2.", "correct": false}, {"id": "b", "text": "P.S.I.", "correct": false}, {"id": "c", "text": "no units.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The value of stress for a given material can be derived by', '[{"id": "a", "text": "Cross sectional area / Load.", "correct": false}, {"id": "b", "text": "Load * Cross sectional area.", "correct": false}, {"id": "c", "text": "Load / Cross sectional area.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What type of a test involves stretching material until it breaks?', '[{"id": "a", "text": "Fatigue Testing.", "correct": false}, {"id": "b", "text": "Hardness Testing.", "correct": false}, {"id": "c", "text": "Tensile Testing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Adhesives containing phenol-formaldehyde, to cure, requires', '[{"id": "a", "text": "room temperature.", "correct": false}, {"id": "b", "text": "high temperature.", "correct": true}, {"id": "c", "text": "low temperature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Two parts of the adhesive process are', '[{"id": "a", "text": "wetting and gripping.", "correct": false}, {"id": "b", "text": "spreading and setting.", "correct": false}, {"id": "c", "text": "wetting and setting.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Types of adhesive joints are', '[{"id": "a", "text": "mechanical and cemented.", "correct": false}, {"id": "b", "text": "cemented and specific.", "correct": false}, {"id": "c", "text": "mechanical and specific.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What material would be used where a high temperature application is required, e.g. a firewall?', '[{"id": "a", "text": "Aramid (Kevlar) fibres.", "correct": false}, {"id": "b", "text": "Carbon/graphite fibres.", "correct": false}, {"id": "c", "text": "Ceramic fibres.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Over extended honeycomb can bend in which direction?', '[{"id": "a", "text": "In all directions.", "correct": false}, {"id": "b", "text": "Across the ribbon.", "correct": true}, {"id": "c", "text": "Along the ribbon.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Fibre weave strength is greatest in the direction of the', '[{"id": "a", "text": "weft.", "correct": false}, {"id": "b", "text": "warp.", "correct": true}, {"id": "c", "text": "bias.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is Alumina?', '[{"id": "a", "text": "An alloy of aluminium.", "correct": false}, {"id": "b", "text": "Aluminium ore.", "correct": false}, {"id": "c", "text": "A ceramic oxide of aluminium.", "correct": true}]'::jsonb, '{B1,B2}'),
