    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of the following could best be manufactured from Perspex panel?', '[{"id": "a", "text": "A passenger window.", "correct": true}, {"id": "b", "text": "A radome.", "correct": false}, {"id": "c", "text": "A cockpit windscreen.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Kevlar and Nomex are types of', '[{"id": "a", "text": "glass fibre composite.", "correct": false}, {"id": "b", "text": "advanced composite.", "correct": true}, {"id": "c", "text": "aluminium alloy.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Strength of fibreglass is', '[{"id": "a", "text": "either direction.", "correct": false}, {"id": "b", "text": "along the fibre.", "correct": true}, {"id": "c", "text": "across the fibre.", "correct": false}]'::jsonb, '{B1,B2}'),
