    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Sound is best absorbed by a material which is', '[{"id": "a", "text": "dense.", "correct": false}, {"id": "b", "text": "soft and porous.", "correct": true}, {"id": "c", "text": "hard.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The maximum tensile strength of fibre reinforced plastic is achieved using', '[{"id": "a", "text": "fibres uniformly distributed at 45 degrees to each other.", "correct": false}, {"id": "b", "text": "unidirectional fibres.", "correct": true}, {"id": "c", "text": "chopped strand mat.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Polyester resin and glass fibre cloth, becomes', '[{"id": "a", "text": "PTFE.", "correct": false}, {"id": "b", "text": "PVC.", "correct": false}, {"id": "c", "text": "GRP.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A thermoplastic can be', '[{"id": "a", "text": "heated and formed only once.", "correct": false}, {"id": "b", "text": "unaffected by even low temperatures.", "correct": false}, {"id": "c", "text": "reheated and reformed more than once.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'An impact adhesive is part of the', '[{"id": "a", "text": "thermoplastic group.", "correct": true}, {"id": "b", "text": "thermoset group.", "correct": false}, {"id": "c", "text": "Anaerobic resin group.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Sandwich panels made of metal honeycomb construction are used on modern aircraft because this type of construction', '[{"id": "a", "text": "may be repaired by gluing replacement skin to the inner core material with thermoplastic resin.", "correct": false}, {"id": "b", "text": "is lighter than single sheet skin of the same strength and is more corrosion resistant.", "correct": false}, {"id": "c", "text": "has a high strength to weight ratio.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A category of plastic material that is capable of softening or flowing when reheated is described as a', '[{"id": "a", "text": "thermoset.", "correct": false}, {"id": "b", "text": "thermoplastic.", "correct": true}, {"id": "c", "text": "thermocure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The classification of high tensile strength fibreglass used in aircraft structures is', '[{"id": "a", "text": "G-glass.", "correct": false}, {"id": "b", "text": "E-glass.", "correct": false}, {"id": "c", "text": "S-glass.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which is the identifying characteristic of acrylic plastics?', '[{"id": "a", "text": "Acetone will soften the plastic, but will not change its colour.", "correct": false}, {"id": "b", "text": "Has a yellowish tint when viewed from the edge.", "correct": true}, {"id": "c", "text": "Zinc chloride will have no effect.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The classification for fibreglass reinforcement material that is high resistivity and the most common is', '[{"id": "a", "text": "E-glass.", "correct": true}, {"id": "b", "text": "S-glass.", "correct": false}, {"id": "c", "text": "G-glass.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Composite fabric material is considered to be the strongest in what direction?', '[{"id": "a", "text": "Warp.", "correct": true}, {"id": "b", "text": "Bias.", "correct": false}, {"id": "c", "text": "Weft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of the following are generally characteristic of aramid fibre (Kevlar) composites?', '[{"id": "a", "text": "High tensile strength and flexibility.", "correct": true}, {"id": "b", "text": "Flexibility, stiffness and corrosive effect in contact with aluminium.", "correct": false}, {"id": "c", "text": "High tensile strength, stiffness and ability to conduct electricity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of the following are generally characteristic of carbon/graphite fibre composites?', '[{"id": "a", "text": "Flexibility, High compressive strength and ability to conduct electricity.", "correct": false}, {"id": "b", "text": "Flexibility and high compressive strength.", "correct": false}, {"id": "c", "text": "Stiffness, high compressive strength and corrosive effect in contact with aluminium.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of the following statements is true about thermosetting plastics?', '[{"id": "a", "text": "They are also known as Teflon.", "correct": false}, {"id": "b", "text": "Once moulded into shape they become set and cannot subsequently be softened by reheating.", "correct": true}, {"id": "c", "text": "They become plastic when heat is applied.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What tests are done on adhesive joints?', '[{"id": "a", "text": "Shear and peel.", "correct": true}, {"id": "b", "text": "Impact and peel.", "correct": false}, {"id": "c", "text": "Impact and shear.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When using a hot bonder to effect a composite repair, you use', '[{"id": "a", "text": "inorganic resin adhesives.", "correct": false}, {"id": "b", "text": "organic resin adhesives.", "correct": false}, {"id": "c", "text": "synthetic resin adhesives.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In a composite repair lay-up, how much should each layer extend beyond the layer below it? [see note]', '[{"id": "a", "text": "3 - 4 inches.", "correct": false}, {"id": "b", "text": "1 - 2 inches.", "correct": true}, {"id": "c", "text": "2 - 3 inches.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the effect of heat on a cold cure resin?', '[{"id": "a", "text": "No effect on pot life.", "correct": false}, {"id": "b", "text": "Decrease pot life.", "correct": true}, {"id": "c", "text": "Increase pot life.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'If you increase the amount of catalyst in a resin mixture,', '[{"id": "a", "text": "the material will become stronger.", "correct": false}, {"id": "b", "text": "the material will become weaker.", "correct": false}, {"id": "c", "text": "the pot life will be decreased.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What two components of a three part polyester resin are dangerous to mix together directly?', '[{"id": "a", "text": "Catalyst and resin.", "correct": false}, {"id": "b", "text": "Accelerator and free catalyst.", "correct": true}, {"id": "c", "text": "Accelerator and resin.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the effect of adding too much hardener to a resin?', '[{"id": "a", "text": "No effect.", "correct": false}, {"id": "b", "text": "Makes the repair more brittle.", "correct": true}, {"id": "c", "text": "The resin will not harden.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the largest hole in honeycomb repairable with microballoons? [see note]', '[{"id": "a", "text": "2.54 inches.", "correct": false}, {"id": "b", "text": "2.54 mm.", "correct": false}, {"id": "c", "text": "2.54 cm.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'An air driven router is used to remove honeycomb material for repairs', '[{"id": "a", "text": "when one outer skin is damaged.", "correct": true}, {"id": "b", "text": "to stainless steel honeycomb only.", "correct": false}, {"id": "c", "text": "when both outer skins are damaged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Where would you use a Tempilstik?', '[{"id": "a", "text": "For the boundary marking of a composite repair.", "correct": false}, {"id": "b", "text": "To indicate temperature when a repaired composite item is cured with heat lamps.", "correct": true}, {"id": "c", "text": "As a temporary repair in a glass fibre internal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The vacuum connections on a fibreglass repair must be placed onto the', '[{"id": "a", "text": "top layer of glass fabric directly.", "correct": false}, {"id": "b", "text": "breather mat.", "correct": true}, {"id": "c", "text": "peel ply.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What do you do if you forget to add hardener to a composite repair?', '[{"id": "a", "text": "Add hardener at the edges and it will cure.", "correct": false}, {"id": "b", "text": "It will cure eventually anyway.", "correct": false}, {"id": "c", "text": "Remove all resin and start again.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Why would you use microballoons as a filler?', '[{"id": "a", "text": "It is the lightest filler material.", "correct": true}, {"id": "b", "text": "It is the cheapest filler material.", "correct": false}, {"id": "c", "text": "It cross-links with the panel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When using a backing former on a composite repair you need to use', '[{"id": "a", "text": "a vacuum bag.", "correct": false}, {"id": "b", "text": "cellophane.", "correct": true}, {"id": "c", "text": "breather cloth.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Heater mats should overlap the repair by', '[{"id": "a", "text": "4 inches.", "correct": false}, {"id": "b", "text": "6 inches.", "correct": false}, {"id": "c", "text": "2 inches.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A thermoplastic fibre reinforced composite is prepared by', '[{"id": "a", "text": "a solvent wipe.", "correct": false}, {"id": "b", "text": "corona method.", "correct": true}, {"id": "c", "text": "etching.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'During vacuum bag lay-up the vacuum gauge is placed where?', '[{"id": "a", "text": "Next to the vacuum port.", "correct": false}, {"id": "b", "text": "Opposite side to the vacuum port.", "correct": true}, {"id": "c", "text": "Over the repair.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Stepped curing has [see note]', '[{"id": "a", "text": "2 or more arrest points.", "correct": false}, {"id": "b", "text": "no arrest point.", "correct": false}, {"id": "c", "text": "1 arrest point.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Maximum repair dimensions for use of microballoons is [see note]', '[{"id": "a", "text": "10mm.", "correct": false}, {"id": "b", "text": "20mm.", "correct": true}, {"id": "c", "text": "30mm.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In an autoclave what pressure would the vacuum alarm be set at?', '[{"id": "a", "text": "Operating pressure.", "correct": false}, {"id": "b", "text": "Higher than operating pressure.", "correct": false}, {"id": "c", "text": "Lower than operating pressure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In an autoclave what would you cover the repair in?', '[{"id": "a", "text": "High temp nylon.", "correct": true}, {"id": "b", "text": "Polypropylene.", "correct": false}, {"id": "c", "text": "Polythene.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When mixing resin it is dangerous to add', '[{"id": "a", "text": "accelerator and catalyst before resin.", "correct": true}, {"id": "b", "text": "catalyst and resin before accelerator.", "correct": false}, {"id": "c", "text": "resin and accelerator before catalyst.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In an autoclave, to apply pressure', '[{"id": "a", "text": "a vacuum bag is used.", "correct": true}, {"id": "b", "text": "weights are used.", "correct": false}, {"id": "c", "text": "clamps are used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What does MSDS stand for?', '[{"id": "a", "text": "Metal Surface Dimension Sector.", "correct": false}, {"id": "b", "text": "Material Safety Data Sheet.", "correct": true}, {"id": "c", "text": "Maximum Structural Design System.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Honeycomb for repair can be removed with', '[{"id": "a", "text": "a drill.", "correct": false}, {"id": "b", "text": "locally manufactured concave knife.", "correct": false}, {"id": "c", "text": "a router.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The pot life of a cold cured resin', '[{"id": "a", "text": "is not reliant upon temperature fluctuations.", "correct": false}, {"id": "b", "text": "decreases with an increase in temperature.", "correct": true}, {"id": "c", "text": "increases with increase of temperature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Thermosetting adhesive, during their curing cycle give off', '[{"id": "a", "text": "static radiation.", "correct": false}, {"id": "b", "text": "heat.", "correct": true}, {"id": "c", "text": "carbon monoxide.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The effect of a lower temperature than ambient during the curing period of a resin, will cause the curing time to', '[{"id": "a", "text": "decrease.", "correct": false}, {"id": "b", "text": "increase.", "correct": true}, {"id": "c", "text": "remain unchanged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is used as the base covering on a honeycomb repair?', '[{"id": "a", "text": "Glass cloth or thin aluminium sheet.", "correct": true}, {"id": "b", "text": "Thick aluminium sheet.", "correct": false}, {"id": "c", "text": "Plywood.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When drilling a carbon fibre reinforced plastic use', '[{"id": "a", "text": "a steel drill and carborundum powder.", "correct": false}, {"id": "b", "text": "a tungsten drill with a pointed tip.", "correct": false}, {"id": "c", "text": "a tungsten carbide drill.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When laying up a glass fibre repair, the extra layer of fibre is', '[{"id": "a", "text": "a sacrificial layer for sanding.", "correct": true}, {"id": "b", "text": "for extra strength.", "correct": false}, {"id": "c", "text": "for shrinkage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Bubbles are removed from a wet composite lay-up by', '[{"id": "a", "text": "application of pressure.", "correct": false}, {"id": "b", "text": "use of a roller.", "correct": true}, {"id": "c", "text": "application of vacuum.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Use of excessive hardener in polyester resin leads to', '[{"id": "a", "text": "a less stiff joint.", "correct": false}, {"id": "b", "text": "reduced pot life.", "correct": false}, {"id": "c", "text": "stiffer joint.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When the rise in temperature during a hot bonded repair is paused, it is known as', '[{"id": "a", "text": "arrest point.", "correct": true}, {"id": "b", "text": "ramping down.", "correct": false}, {"id": "c", "text": "ramping up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Slight waviness on a fibre composite structure', '[{"id": "a", "text": "may cause a fatigue crack eventually.", "correct": false}, {"id": "b", "text": "may be tolerable if lightly loaded.", "correct": true}, {"id": "c", "text": "could be reinforced with additional plies over the weakened area.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The maximum length of time a component is held in stores is known as the', '[{"id": "a", "text": "package life.", "correct": false}, {"id": "b", "text": "storage life.", "correct": false}, {"id": "c", "text": "shelf life.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'On a pre-preg composite', '[{"id": "a", "text": "life can be extended by 12 months if stored below -18 °C.", "correct": true}, {"id": "b", "text": "life can be extended by 12 months if stored above 40 °C.", "correct": false}, {"id": "c", "text": "no life extension is allowed, it must be used immediately.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A hot bonded composite panel has a crack. When it reaches the ribbon it will', '[{"id": "a", "text": "carry on along the ribbon.", "correct": false}, {"id": "b", "text": "have no effect on its direction.", "correct": false}, {"id": "c", "text": "stop.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In an autoclave the air is removed by', '[{"id": "a", "text": "pressure.", "correct": false}, {"id": "b", "text": "roller.", "correct": false}, {"id": "c", "text": "vacuum.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the separation of an aramid panel layers described as?', '[{"id": "a", "text": "Delamination.", "correct": true}, {"id": "b", "text": "Debonding.", "correct": false}, {"id": "c", "text": "Detachment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Tap testing a sandwich panel construction', '[{"id": "a", "text": "is not an approved method of testing.", "correct": false}, {"id": "b", "text": "will not give very reliable results.", "correct": false}, {"id": "c", "text": "is crude, but works remarkably well.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which product is a serious health hazard when handling?', '[{"id": "a", "text": "Ceramic.", "correct": false}, {"id": "b", "text": "Asbestos.", "correct": true}, {"id": "c", "text": "Glass fibre.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Aircraft transparent plastics are cleaned using', '[{"id": "a", "text": "warm soapy water, rinsed and dried.", "correct": true}, {"id": "b", "text": "paraffin and soft cotton pad.", "correct": false}, {"id": "c", "text": "clean dry soft leather.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A thermosetting adhesive', '[{"id": "a", "text": "will be resistant to heat.", "correct": false}, {"id": "b", "text": "can be re-formed when hot.", "correct": false}, {"id": "c", "text": "undergoes a chemical transformation and creates an insoluble substance.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Metal fasteners used with carbon/graphite composite structures', '[{"id": "a", "text": "must be made of materials such as titanium or corrosion resistant steel.", "correct": true}, {"id": "b", "text": "must be made of high strength aluminium alloy.", "correct": false}, {"id": "c", "text": "may be made of any of the metals commonly used in aircraft fasteners.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which methods can be used to inspect fibreglass/honeycomb structures for entrapped water?', '[{"id": "a", "text": "Acoustic emission and X-ray.", "correct": false}, {"id": "b", "text": "X-ray and back-lighting.", "correct": true}, {"id": "c", "text": "Acoustic emission and back-lighting.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When balsa wood is used to replace a damaged honeycomb core, the plug should be cut so that', '[{"id": "a", "text": "it is about 1/8 inch undersize to allow sufficient bonding material to be applied.", "correct": false}, {"id": "b", "text": "the grain is parallel to the skin.", "correct": false}, {"id": "c", "text": "the grain is perpendicular to the skin.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When repairing puncture-type damage of a metal faced laminated honeycomb panel, the edges of the doubler should be tapered to', '[{"id": "a", "text": "whatever is desired for a neat clean appearance.", "correct": false}, {"id": "b", "text": "two times the thickness of the metal.", "correct": false}, {"id": "c", "text": "100 times the thickness of the metal.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'One of the best ways to assure that a properly prepared batch of matrix resin has been achieved is to', '[{"id": "a", "text": "test the viscosity of the resin immediately after mixing.", "correct": false}, {"id": "b", "text": "have mixed enough for a test sample.", "correct": true}, {"id": "c", "text": "perform a chemical composition analysis.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of the following are advantages of using microballoons in repairs to laminate honeycomb sandwich panels?', '[{"id": "a", "text": "Greater concentrations of resin in edges and corners, improved strength to weight ratio, less density, lower", "correct": false}, {"id": "b", "text": "Less density, lower stress concentrations.", "correct": true}, {"id": "c", "text": "Improved strength to weight ratio, less density, lower stress.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The length and time that a catalyzed resin will remain in a workable state is called the', '[{"id": "a", "text": "shelf life.", "correct": false}, {"id": "b", "text": "service life.", "correct": false}, {"id": "c", "text": "pot life.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'One method of inspecting a laminated fibreglass structure that has been subjected to damage is', '[{"id": "a", "text": "strip the damaged area of all paint and shine a strong light through the structure.", "correct": true}, {"id": "b", "text": "use an eddy current probe on both sides of the damaged area.", "correct": false}, {"id": "c", "text": "use dye-penetrant inspection procedures, exposing the entire damaged area to the penetrant solution.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When inspecting a composite panel using the ring test/tapping method, a dull thud may indicate', '[{"id": "a", "text": "an area of too much matrix between the fibres.", "correct": false}, {"id": "b", "text": "less than full strength curing of the matrix.", "correct": false}, {"id": "c", "text": "separation of the laminates.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Superficial scars, scratches, surface abrasion, or rain erosion on fibreglass laminates can generally be repaired by applying', '[{"id": "a", "text": "one or more coats of suitable resin (room-temperature catalyzed) to the surface.", "correct": true}, {"id": "b", "text": "a sheet of polyethylene over the abraded surface and one or more coats of resin cured with infrared heat", "correct": false}, {"id": "c", "text": "a piece of resin-impregnated glass fabric facing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A potted compound repair on honeycomb can usually be made on damages less than', '[{"id": "a", "text": "4 inches in diameter.", "correct": false}, {"id": "b", "text": "2 inches in diameter.", "correct": false}, {"id": "c", "text": "1 inch in diameter.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What reference tool is used to determine how the fibre is to be oriented for a particular ply or fabric?', '[{"id": "a", "text": "Bias clock.", "correct": false}, {"id": "b", "text": "Weft clock.", "correct": false}, {"id": "c", "text": "Warp clock.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The strength and stiffness of a properly constructed composite lay-up depends primarily on', '[{"id": "a", "text": "the ability of the fibres to transfer stress to the matrix.", "correct": false}, {"id": "b", "text": "a 60% matrix to 40% fibre ratio.", "correct": false}, {"id": "c", "text": "the orientation of the plies to the load direction.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which fibre to resin (%) ratio for advanced composite wet lay-ups is generally considered the best?', '[{"id": "a", "text": "60:40.", "correct": true}, {"id": "b", "text": "50:50.", "correct": false}, {"id": "c", "text": "40:60.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the material layer used within the vacuum bag pressure system to absorb excess resin during curing called?', '[{"id": "a", "text": "Breather.", "correct": false}, {"id": "b", "text": "Bleeder.", "correct": true}, {"id": "c", "text": "Release.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When necessary, what type of cutting fluid is usually acceptable for machining composite laminates?', '[{"id": "a", "text": "Water soluble oil.", "correct": false}, {"id": "b", "text": "Water only.", "correct": true}, {"id": "c", "text": "Water displacing oil.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Fibreglass laminate damage not exceeding the first layer or ply can be repaired by', '[{"id": "a", "text": "filling with putty consisting of compatible resin and clean, short glass fibres.", "correct": true}, {"id": "b", "text": "sanding the damaged are until aerodynamically smooth.", "correct": false}, {"id": "c", "text": "trimming the rough edges and sealing with paint.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Fibreglass damage that extends completely through a laminated sandwich structure', '[{"id": "a", "text": "may be filled with resin to eliminate dangerous stress concentrations.", "correct": false}, {"id": "b", "text": "must be repaired.", "correct": true}, {"id": "c", "text": "may be filled with putty which is compatible with the resin.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Fibreglass laminate damage that extends completely through one facing and into the core', '[{"id": "a", "text": "can be repaired by using a typical facing patch.", "correct": false}, {"id": "b", "text": "requires replacement of the damaged core and facing.", "correct": true}, {"id": "c", "text": "cannot be repaired.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of the following, when added to wet resins, provide strength for the repair of damaged fastener holes in composite panels?', '[{"id": "a", "text": "microballoons, cotton flock and chopped fibres.", "correct": false}, {"id": "b", "text": "Cotton flock and chopped fibres.", "correct": true}, {"id": "c", "text": "Microballoons and chopped fibres.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The part of a replacement honeycomb core that must line up with the adjacent original is the', '[{"id": "a", "text": "cell edge.", "correct": false}, {"id": "b", "text": "cell side.", "correct": false}, {"id": "c", "text": "ribbon direction.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of the following is the definition of cure time?', '[{"id": "a", "text": "The period after which the surface of the compound no longer exhibits adhesive properties.", "correct": false}, {"id": "b", "text": "The time required for the mixed compound to reach an initial rubbery state.", "correct": false}, {"id": "c", "text": "The time taken for the mixed compound to reach a final rubbery state.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In order to prevent dermatitis caused due to contact with polymer resin, one should', '[{"id": "a", "text": "use disposable gloves or barrier cream.", "correct": true}, {"id": "b", "text": "remember to close the autoclave door during curing.", "correct": false}, {"id": "c", "text": "avoid inhaling fumes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'With what would you check the bonded joints of a wooden aircraft structure?', '[{"id": "a", "text": "A feeler gauge.", "correct": true}, {"id": "b", "text": "A plastic strip.", "correct": false}, {"id": "c", "text": "A screwdriver.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The defects not allowed at all on wooden structures are', '[{"id": "a", "text": "mineral streaks.", "correct": false}, {"id": "b", "text": "pitch pockets.", "correct": false}, {"id": "c", "text": "checks, shakes and splits.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The basic structure of an aircraft made of wood can be', '[{"id": "a", "text": "monocoque.", "correct": false}, {"id": "b", "text": "non-monocoque.", "correct": false}, {"id": "c", "text": "non-monocoque, monocoque or semi-monocoque.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When a full inspection for deterioration is to be carried out on a wooden aircraft, you would', '[{"id": "a", "text": "Bring the aircraft into the hangar for 2 to 3 days prior to the inspection.", "correct": true}, {"id": "b", "text": "Jack and trestle the aircraft to the rigging position.", "correct": false}, {"id": "c", "text": "Remove all the fabric/cloth prior to inspection.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'For fungus to cause wood decay in a wood structure, the moisture content in the wood must be at least', '[{"id": "a", "text": "20%.", "correct": true}, {"id": "b", "text": "85%.", "correct": false}, {"id": "c", "text": "5%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The normal moisture content in the wood of a wooden aircraft structure is', '[{"id": "a", "text": "10-12%.", "correct": true}, {"id": "b", "text": "20-30%.", "correct": false}, {"id": "c", "text": "0-2%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How is the moisture content within the wood of a wood aircraft structure determined?', '[{"id": "a", "text": "By inserting the probe of a moisture meter.", "correct": true}, {"id": "b", "text": "By measuring the size of the water stains at joints.", "correct": false}, {"id": "c", "text": "By weighing the wood structure before and after drying it.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Except where specified by the manufacturer, a wooden spar may be spliced', '[{"id": "a", "text": "at no point.", "correct": false}, {"id": "b", "text": "at any point except under the wing attachment fittings.", "correct": true}, {"id": "c", "text": "at any point.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Replacement of a wooden spar is', '[{"id": "a", "text": "only permitted by the manufacturer.", "correct": false}, {"id": "b", "text": "a minor repair.", "correct": false}, {"id": "c", "text": "a major repair.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A crack is found in a wooden spar, you', '[{"id": "a", "text": "must replace the spar section.", "correct": false}, {"id": "b", "text": "might be able to repair the spar.", "correct": true}, {"id": "c", "text": "must replace the entire spar.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Wood sealants used on wooden aircraft structures are for', '[{"id": "a", "text": "helping to prevent wood cracking.", "correct": true}, {"id": "b", "text": "improving aerodynamic efficiency.", "correct": false}, {"id": "c", "text": "reducing the requirement for sanding.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'To determine whether an aircraft wooden structure surface is compound curvature, you would use', '[{"id": "a", "text": "a curvature gauge.", "correct": false}, {"id": "b", "text": "a sheet of paper.", "correct": true}, {"id": "c", "text": "a trammel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'To assist the bending of plywood, a heated bending former must be heated to a temperature of', '[{"id": "a", "text": "300 °C.", "correct": false}, {"id": "b", "text": "150 °C.", "correct": false}, {"id": "c", "text": "100 °C.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A splayed patch repair may be used on plywood damage which does not exceed', '[{"id": "a", "text": "20 times the skin thickness.", "correct": false}, {"id": "b", "text": "15 times the skin thickness.", "correct": true}, {"id": "c", "text": "10 times the skin thickness.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A surface patch to a plywood structure may be a large as [see note]', '[{"id": "a", "text": "50 sq.inch area.", "correct": true}, {"id": "b", "text": "50 inch perimeter.", "correct": false}, {"id": "c", "text": "50 inch diameter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The steepest slope permitted on the scarf of a scarfed plywood repair is', '[{"id": "a", "text": "1 in 20.", "correct": false}, {"id": "b", "text": "1 in 4.", "correct": false}, {"id": "c", "text": "1 in 12.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The maximum size damage to plywood skin that may be repaired with a fabric patch is', '[{"id": "a", "text": "3.0 inch diameter.", "correct": false}, {"id": "b", "text": "0.5 inch diameter.", "correct": false}, {"id": "c", "text": "1.0 inch diameter.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The doubler used to support a scarfed patch plywood repair should be made from plywood of a minimum', '[{"id": "a", "text": "1/4 inch thick.", "correct": true}, {"id": "b", "text": "1/8 inch thick.", "correct": false}, {"id": "c", "text": "3/8 inch thick.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'An aircraft wooden structure must be surface finished and sealed', '[{"id": "a", "text": "on both the outer and inner surfaces.", "correct": true}, {"id": "b", "text": "on the inner surfaces only.", "correct": false}, {"id": "c", "text": "on the outer surfaces only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Pine has a strength, compared with that of spruce, which is', '[{"id": "a", "text": "less than that of spruce.", "correct": true}, {"id": "b", "text": "greater than that of spruce.", "correct": false}, {"id": "c", "text": "the same as that of spruce.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The standard wood type for aircraft wood structures is', '[{"id": "a", "text": "spruce.", "correct": true}, {"id": "b", "text": "douglas fir.", "correct": false}, {"id": "c", "text": "pine.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Hard knots in wood are acceptable', '[{"id": "a", "text": "in certain locations.", "correct": true}, {"id": "b", "text": "never.", "correct": false}, {"id": "c", "text": "up to 3/8 inch diameter in any location.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Wood with checks, shakes or splits', '[{"id": "a", "text": "can be used providing the damage is repaired by gluing and clamping.", "correct": false}, {"id": "b", "text": "can be used for certain secondary structure.", "correct": false}, {"id": "c", "text": "must be rejected.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Compression wood', '[{"id": "a", "text": "is a hard-wood.", "correct": false}, {"id": "b", "text": "should be rejected.", "correct": true}, {"id": "c", "text": "is preferred because of its superior strength qualities.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Red heart and purple heart', '[{"id": "a", "text": "are types of hard-wood.", "correct": false}, {"id": "b", "text": "are forms of decay in wood.", "correct": true}, {"id": "c", "text": "are harmless natural defects in wood.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The greatest amount of shrinkage in wood is in which direction?', '[{"id": "a", "text": "Tangential.", "correct": true}, {"id": "b", "text": "Radial.", "correct": false}, {"id": "c", "text": "The shrinkage is equal in tangential and radial directions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Shrinkage of wood is', '[{"id": "a", "text": "equal along and across the fibres.", "correct": false}, {"id": "b", "text": "least along the fibres.", "correct": true}, {"id": "c", "text": "least across the fibres.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Shrinkage of wood is', '[{"id": "a", "text": "greatest in the longitudinal direction.", "correct": false}, {"id": "b", "text": "negligible in the longitudinal direction.", "correct": true}, {"id": "c", "text": "negligible in the radial direction.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The maximum permissible grain deviation in wood is', '[{"id": "a", "text": "1:8.", "correct": false}, {"id": "b", "text": "1:20.", "correct": false}, {"id": "c", "text": "1:15.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Small (up to 3/8 inch diameter) hard-knots are allowed in a wooden spar [see note]', '[{"id": "a", "text": "in the middle 1/3 portion.", "correct": true}, {"id": "b", "text": "nowhere.", "correct": false}, {"id": "c", "text": "in the outer 1/3 portions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Bolt holes through wooden structures should be', '[{"id": "a", "text": "sealed, and the sealant allowed to dry before fitting the bolt.", "correct": false}, {"id": "b", "text": "left unsealed and unvarnished inside the hole.", "correct": false}, {"id": "c", "text": "sealed with varnish and wet-assembled with the bolt before the varnish has dried.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Wood end-grain', '[{"id": "a", "text": "has the same susceptibility to moisture ingress as the side of the grain.", "correct": false}, {"id": "b", "text": "is less susceptible to moisture ingress as the side of the grain.", "correct": false}, {"id": "c", "text": "is more susceptible to moisture ingress as the side of the grain.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In cases of elongated boltholes in a wood spar or cracks in the vicinity of the boltholes', '[{"id": "a", "text": "it is permissible to ream the hole, plug with hardwood and re-drill.", "correct": false}, {"id": "b", "text": "a new section of spar should be spliced in or the spar entirely replaced.", "correct": true}, {"id": "c", "text": "the spar may be reinforced by using hardwood reinforcing plates.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A faint line running across the grain of a wood spar generally indicates', '[{"id": "a", "text": "shear failure.", "correct": false}, {"id": "b", "text": "decay.", "correct": false}, {"id": "c", "text": "compression failure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The I-beam wooden spar is routed to', '[{"id": "a", "text": "obtain uniform strength.", "correct": false}, {"id": "b", "text": "decrease weight.", "correct": true}, {"id": "c", "text": "increase strength.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Pin knot clusters are permitted in wood aircraft structure provided', '[{"id": "a", "text": "they have no mineral streaks.", "correct": false}, {"id": "b", "text": "no pitch pockets are within 12 inches.", "correct": false}, {"id": "c", "text": "they produce a small effect of grain direction.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Compression failures in wood aircraft structures are characterised by buckling of the fibres that appear as streaks on the surface', '[{"id": "a", "text": "parallel to the grain.", "correct": false}, {"id": "b", "text": "at right-angles to the growth rings.", "correct": false}, {"id": "c", "text": "at right angles to the grain.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Fabrics may be fitted to airframe structures by', '[{"id": "a", "text": "always riveting.", "correct": false}, {"id": "b", "text": "wood nails.", "correct": false}, {"id": "c", "text": "tying on with string.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Aircraft fabric covering is made from', '[{"id": "a", "text": "silk.", "correct": false}, {"id": "b", "text": "polyester.", "correct": true}, {"id": "c", "text": "nylon.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'At manufacture, aircraft fabric is [see note]', '[{"id": "a", "text": "shrunk.", "correct": true}, {"id": "b", "text": "doped.", "correct": false}, {"id": "c", "text": "stretched.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Recovering or repairing of an aircraft with a fabric other than the original fabric type is', '[{"id": "a", "text": "a major modification and requires approval.", "correct": true}, {"id": "b", "text": "prohibited.", "correct": false}, {"id": "c", "text": "a minor modification, providing the fabric is the same strength as the original.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Reinforcing tape used on aircraft fabric covering must have a minimum strength of', '[{"id": "a", "text": "80 lb.", "correct": false}, {"id": "b", "text": "40 lb.", "correct": false}, {"id": "c", "text": "120 lb.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Lacing cord used on aircraft fabric covering must have a minimum breaking strength of', '[{"id": "a", "text": "120 lb.", "correct": false}, {"id": "b", "text": "80 lb.", "correct": true}, {"id": "c", "text": "40 lb.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Fabric seams are preferable', '[{"id": "a", "text": "parallel to the line of flight.", "correct": true}, {"id": "b", "text": "spanwise to the line of flight.", "correct": false}, {"id": "c", "text": "oblique to the line of flight.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Single stitched machine sewn seams are permissible', '[{"id": "a", "text": "at all locations on the aircraft.", "correct": false}, {"id": "b", "text": "never.", "correct": false}, {"id": "c", "text": "only when positioned over a structure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The minimum pitch of hand-sewn stitch is', '[{"id": "a", "text": "1/4 inch.", "correct": true}, {"id": "b", "text": "equal to 10 times the thread thickness.", "correct": false}, {"id": "c", "text": "4 inches.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Hand sewn stitch must be locked at a minimum of', '[{"id": "a", "text": "the end of the stitch only.", "correct": false}, {"id": "b", "text": "20 stitch intervals.", "correct": false}, {"id": "c", "text": "10 stitch intervals.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Fabric to be hand sewn must be doubled under at the edge to a minimum distance of [see note]', '[{"id": "a", "text": "1/2 inch.", "correct": true}, {"id": "b", "text": "3/8 inch.", "correct": false}, {"id": "c", "text": "1/4 inch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Holes are cut in fabric for inspection panels, spar fittings, drain grommets etc', '[{"id": "a", "text": "after doping.", "correct": true}, {"id": "b", "text": "before doping.", "correct": false}, {"id": "c", "text": "before attaching the fabric to the structure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Aircraft fabric lacing cord is reinforced with', '[{"id": "a", "text": "epoxy.", "correct": false}, {"id": "b", "text": "wax.", "correct": true}, {"id": "c", "text": "lanolin.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The two preferred types of dope used on aircraft fabric covering is', '[{"id": "a", "text": "cellulose and polyester.", "correct": false}, {"id": "b", "text": "cellulose and butyrate.", "correct": false}, {"id": "c", "text": "nitrate and butyrate.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Aircraft dope, during storage in adverse conditions in a store-room, will become', '[{"id": "a", "text": "acidic.", "correct": true}, {"id": "b", "text": "discoloured.", "correct": false}, {"id": "c", "text": "alkaline.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What type of dope is preferred for use on natural fiber aircraft covering?', '[{"id": "a", "text": "Nitrate.", "correct": true}, {"id": "b", "text": "Any type of dope is suitable.", "correct": false}, {"id": "c", "text": "Butyrate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of the following is true regarding aircraft dope type?', '[{"id": "a", "text": "Nitrate dope may be applied over the top of butyrate dope.", "correct": false}, {"id": "b", "text": "Butyrate dope may be applied over the top of nitrate dope.", "correct": true}, {"id": "c", "text": "Either type of dope may be applied over the top of any type of dope.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What type of shoes should be worn by the technician applying a dope finish to a fabric covered aircraft?', '[{"id": "a", "text": "Rubber soled.", "correct": true}, {"id": "b", "text": "Leather soled.", "correct": false}, {"id": "c", "text": "Plastic uppers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What are the limits of the environmental conditions for applying dope to a fabric covered aircraft?', '[{"id": "a", "text": "Relative humidity 50 - 70%, temperature range 40 ° to 60 °F.", "correct": false}, {"id": "b", "text": "Relative humidity 50 - 75%, temperature range 65 ° to 75 °F.", "correct": false}, {"id": "c", "text": "Relative humidity 20 - 60%, temperature range 65 ° to 75 °F.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Applying dope to a fabric covered aircraft should be done by', '[{"id": "a", "text": "spraying all coats to avoid brush marks.", "correct": false}, {"id": "b", "text": "spray all coats except the first three.", "correct": true}, {"id": "c", "text": "brushing all coats to ensure it is absorbed into the fabric.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Regarding the thinning of aircraft dope', '[{"id": "a", "text": "underthinning is preferred to overthinning.", "correct": false}, {"id": "b", "text": "dope should be thinned with automotive thinners.", "correct": false}, {"id": "c", "text": "overthinning is preferred to underthinning.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A retarder is added to aircraft dope to', '[{"id": "a", "text": "to extend the shelf life.", "correct": false}, {"id": "b", "text": "produce a smoother finish.", "correct": true}, {"id": "c", "text": "to retard the application time.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Doped fabric [see note]', '[{"id": "a", "text": "is not to be treated after application.", "correct": true}, {"id": "b", "text": "is treated with varnish.", "correct": false}, {"id": "c", "text": "is treated with wax compound.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the reason for using aluminium-pigmented dope on a fabric covered aircraft?', '[{"id": "a", "text": "To provide an aluminium colour to the aircraft.", "correct": false}, {"id": "b", "text": "To block UV radiation.", "correct": true}, {"id": "c", "text": "To provide strength.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Aircraft sheet plywood skins are', '[{"id": "a", "text": "sealed and varnished or painted.", "correct": true}, {"id": "b", "text": "sealed and doped.", "correct": false}, {"id": "c", "text": "covered in fabric.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Orange peeling of a doped surface may be caused by', '[{"id": "a", "text": "dope viscosity too low.", "correct": false}, {"id": "b", "text": "dope viscosity too high.", "correct": true}, {"id": "c", "text": "air temperature too low.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Butyrate dope burns', '[{"id": "a", "text": "slower than nitrate dope.", "correct": true}, {"id": "b", "text": "faster than nitrate dope.", "correct": false}, {"id": "c", "text": "the same rate as nitrate dope.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Fabric coated with nitrate dope can be differentiated from fabric coated in butyrate dope by', '[{"id": "a", "text": "smelling the fabric.", "correct": false}, {"id": "b", "text": "carrying out a burn test.", "correct": true}, {"id": "c", "text": "observing the color.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'If the fabric on a wood/fabric aircraft has lost its strength', '[{"id": "a", "text": "the fabric can be treated with a rejuvenator.", "correct": false}, {"id": "b", "text": "the fabric can be treated with additional coats of the approved type of dope.", "correct": false}, {"id": "c", "text": "the fabric must be replaced.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When does an aircraft fabric covering repair become a major repair? [see note]', '[{"id": "a", "text": "When the repair extends over a wing rib.", "correct": false}, {"id": "b", "text": "When the repair extends over three adjacent wing ribs.", "correct": false}, {"id": "c", "text": "When the repair extends over two adjacent wing ribs.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Where the edge of a new fabric section will be located within 1 inch of a structural member to which the fabric is attached by rib lacing or other methods, the new fabric section should', '[{"id": "a", "text": "be extended 3 inches past the structural member.", "correct": true}, {"id": "b", "text": "be extended to meet the structural member.", "correct": false}, {"id": "c", "text": "be designated a major repair.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What width of finishing tape should be used on a tear in a fabric cover which is 10 inches long? [see note]', '[{"id": "a", "text": "2 inches.", "correct": false}, {"id": "b", "text": "6 inches.", "correct": false}, {"id": "c", "text": "4 inches.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What width of finishing tape should be used on a tear in a fabric cover which is 20 inches long? [see note]', '[{"id": "a", "text": "6 inches.", "correct": true}, {"id": "b", "text": "2 inches.", "correct": false}, {"id": "c", "text": "4 inches.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Lines of stitching of a fabric repair are locked at the end with', '[{"id": "a", "text": "a hitch knot.", "correct": false}, {"id": "b", "text": "a half hitch knot.", "correct": false}, {"id": "c", "text": "a double half hitch knot.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Wrinkles in a fabric covering of a wood/fabric aircraft are', '[{"id": "a", "text": "not permitted.", "correct": true}, {"id": "b", "text": "a minor aerodynamic detriment.", "correct": false}, {"id": "c", "text": "permitted only if they are temporary due to damp/wet weather conditions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When and how is finishing tape applied on fabric covered aircraft?', '[{"id": "a", "text": "Doped on immediately prior to the finish coat.", "correct": false}, {"id": "b", "text": "Sewed or laced on before dope is applied.", "correct": false}, {"id": "c", "text": "Doped on after the first or second coat of dope.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The determining factor in the selection of the correct weight of textile fabric to be used in covering any type of aircraft is the', '[{"id": "a", "text": "maximum wing loading.", "correct": false}, {"id": "b", "text": "speed of the aircraft.", "correct": false}, {"id": "c", "text": "speed of the aircraft and the maximum wing loading.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How many fabric thicknesses will be found in a French-fell seam?', '[{"id": "a", "text": "Five.", "correct": false}, {"id": "b", "text": "Three.", "correct": false}, {"id": "c", "text": "Four.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Moisture, mildew, chemicals and acids have no effect on', '[{"id": "a", "text": "glass fabric.", "correct": true}, {"id": "b", "text": "linen fabric.", "correct": false}, {"id": "c", "text": "dacron fabric.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The strength classification of fabric used in aircraft covering is based upon', '[{"id": "a", "text": "bearing strength.", "correct": false}, {"id": "b", "text": "shear strength.", "correct": false}, {"id": "c", "text": "tensile strength.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Fabric rejuvenator', '[{"id": "a", "text": "penetrates the fabric and restores fungicidal resistance.", "correct": false}, {"id": "b", "text": "restores fabric strength and tautness to at least the minimum acceptable level.", "correct": false}, {"id": "c", "text": "restores the condition of the dope coatings.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When testing the strength of Grade A cotton fabric covering an aircraft that requires only intermediate grade, the minimum acceptable strength the fabric must have is', '[{"id": "a", "text": "56 pounds per inch warp and weft.", "correct": false}, {"id": "b", "text": "70% of its original strength.", "correct": false}, {"id": "c", "text": "70% of the original strength for intermediate fabric.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is used to slow the drying time of some dope finishes to prevent blush?', '[{"id": "a", "text": "Rejuvenator.", "correct": false}, {"id": "b", "text": "Reducer.", "correct": false}, {"id": "c", "text": "Retarder.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Aluminium-pigment in dope is used primarily to', '[{"id": "a", "text": "exclude sunlight from the fabric.", "correct": true}, {"id": "b", "text": "provide a silver colour.", "correct": false}, {"id": "c", "text": "aid in sealing out moisture from the fabric.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'From the following list of metals, which is most cathodic?', '[{"id": "a", "text": "Nickel.", "correct": false}, {"id": "b", "text": "Magnesium.", "correct": false}, {"id": "c", "text": "Stainless steel.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Intergranular corrosion is caused by', '[{"id": "a", "text": "improperly assembled components.", "correct": false}, {"id": "b", "text": "improper heat treatment.", "correct": true}, {"id": "c", "text": "dissimilar metal contact.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Corrosion caused by electrolytic action is the result of', '[{"id": "a", "text": "contact between two unlike metals.", "correct": true}, {"id": "b", "text": "excessive anodization.", "correct": false}, {"id": "c", "text": "the wrong quenching agent.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Corrosion may be regarded as the destruction of metal by', '[{"id": "a", "text": "electrochemical action.", "correct": true}, {"id": "b", "text": "hydroelectric action.", "correct": false}, {"id": "c", "text": "electromechanical action.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Exfoliation corrosion is sometimes referred to as', '[{"id": "a", "text": "layer corrosion.", "correct": true}, {"id": "b", "text": "filiform corrosion.", "correct": false}, {"id": "c", "text": "sub-surface corrosion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When dissimilar metals are brought together, or the same metal in different states, one metal forms the anode and the other the cathode. Which will suffer from corrosion?', '[{"id": "a", "text": "Both will corrode equally.", "correct": false}, {"id": "b", "text": "The cathode.", "correct": false}, {"id": "c", "text": "The anode.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In corrosion, the electrode that loses electrons is', '[{"id": "a", "text": "the cathode.", "correct": false}, {"id": "b", "text": "either the cathode or the anode depending upon the electrolyte.", "correct": false}, {"id": "c", "text": "the anode.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of these is a common cause of corrosion?', '[{"id": "a", "text": "Water in fuel.", "correct": false}, {"id": "b", "text": "Spilled battery acid.", "correct": true}, {"id": "c", "text": "Untreated metal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is stress corrosion?', '[{"id": "a", "text": "Corrosion in an area under cyclic loading.", "correct": false}, {"id": "b", "text": "Corrosion due to fretting.", "correct": false}, {"id": "c", "text": "Corrosion in an area under continuous loading.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Electrochemical reaction is caused by the contact of', '[{"id": "a", "text": "bonding.", "correct": false}, {"id": "b", "text": "moisture on the surface of the metal.", "correct": false}, {"id": "c", "text": "dissimilar metals.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Chemical attack is a direct result of', '[{"id": "a", "text": "intergranular corrosion.", "correct": false}, {"id": "b", "text": "cathodic & anodic changes in the material.", "correct": true}, {"id": "c", "text": "filiform corrosion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Galvanic corrosion is caused by', '[{"id": "a", "text": "incorrect heat treatments or incorrect alloying.", "correct": false}, {"id": "b", "text": "cyclic stressing and a decrease in cross sectional area.", "correct": false}, {"id": "c", "text": "the joining of 2 dissimilar metals.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In the galvanic series, the most noble metal will, if joined to another metal', '[{"id": "a", "text": "always be at the top of the table.", "correct": false}, {"id": "b", "text": "corrode before the less noble metal.", "correct": false}, {"id": "c", "text": "allow the less noble metal to corrode first.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Stress corrosion is associated with', '[{"id": "a", "text": "cyclic loading and a corrosion pit.", "correct": false}, {"id": "b", "text": "a corrosion pit in a member under a compressive load.", "correct": false}, {"id": "c", "text": "a corrosion pit in a member under stress.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Corrosion will spread more rapidly when metals are exposed to', '[{"id": "a", "text": "cold climates.", "correct": false}, {"id": "b", "text": "high temperatures.", "correct": true}, {"id": "c", "text": "dry climates.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of the following statements is correct?', '[{"id": "a", "text": "Selenious acid is used for the re-protection of aluminium alloys.", "correct": true}, {"id": "b", "text": "The chemical test for bronze is nitric acid which produces a white precipitate.", "correct": false}, {"id": "c", "text": "All corrosion is a chemical action.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In a poorly produced repair to skin structure, where would stress corrosion start?', '[{"id": "a", "text": "Radiate from the corner or sharp edges.", "correct": true}, {"id": "b", "text": "Along the edges of repair.", "correct": false}, {"id": "c", "text": "Form internally to produce surface corrosion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Some metals are inherently stable. What does this suggest?', '[{"id": "a", "text": "They strongly resist corrosion.", "correct": true}, {"id": "b", "text": "They are highly prone to corrosion.", "correct": false}, {"id": "c", "text": "They try to revert to their natural state.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The oxide film formed on the surface of aluminium is', '[{"id": "a", "text": "non-porous.", "correct": true}, {"id": "b", "text": "porous.", "correct": false}, {"id": "c", "text": "hard and porous.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Corrosion control begins at the', '[{"id": "a", "text": "production stage.", "correct": false}, {"id": "b", "text": "manufacturing stage.", "correct": false}, {"id": "c", "text": "design stage.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Aluminium is', '[{"id": "a", "text": "not resistant to corrosion.", "correct": false}, {"id": "b", "text": "highly resistant to corrosion.", "correct": true}, {"id": "c", "text": "reasonably resistant to corrosion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When galvanic corrosion takes place, which part corrodes?', '[{"id": "a", "text": "Anode.", "correct": true}, {"id": "b", "text": "Oxide film coating.", "correct": false}, {"id": "c", "text": "Cathode.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Corrosion caused by galvanic action is the result of', '[{"id": "a", "text": "contact between two unlike metals.", "correct": true}, {"id": "b", "text": "excessive anodization.", "correct": false}, {"id": "c", "text": "excessive etching.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What sort of corrosion would a magneto be likely to encounter if completely enclosed? [see note]', '[{"id": "a", "text": "None, providing the magneto is completely enclosed.", "correct": false}, {"id": "b", "text": "Direct chemical attack.", "correct": false}, {"id": "c", "text": "Pitting.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What are the signs of fretting corrosion?', '[{"id": "a", "text": "Black powder or cocoa staining.", "correct": true}, {"id": "b", "text": "Intergranular cracking.", "correct": false}, {"id": "c", "text": "Flaking.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Black streaks back from a rivet hole signify', '[{"id": "a", "text": "galvanic corrosion.", "correct": false}, {"id": "b", "text": "intergranular corrosion.", "correct": false}, {"id": "c", "text": "fretting.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When a steel part is welded, corrosion occurs because', '[{"id": "a", "text": "it is affected by spatter.", "correct": false}, {"id": "b", "text": "the strip has become anodic.", "correct": true}, {"id": "c", "text": "paint has been removed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Intergranular corrosion', '[{"id": "a", "text": "can be recognized by a grey powder deposit.", "correct": false}, {"id": "b", "text": "may have no visual surface indication.", "correct": true}, {"id": "c", "text": "can be recognized by its flaking and lifting of the material layers.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Active flux does what?', '[{"id": "a", "text": "Protects.", "correct": false}, {"id": "b", "text": "Cleans.", "correct": false}, {"id": "c", "text": "Both cleans and protects.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Jointing compound is used for what reason?', '[{"id": "a", "text": "To prevent dissimilar metal corrosion.", "correct": true}, {"id": "b", "text": "To bond the components together.", "correct": false}, {"id": "c", "text": "To make the components easier to disassemble.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Galvanic action caused by dissimilar metal contact may best be prevented by', '[{"id": "a", "text": "applying a non-porous dielectric material between the surfaces.", "correct": true}, {"id": "b", "text": "special precautions are not required if they are properly bonded.", "correct": false}, {"id": "c", "text": "priming both the surfaces with a light coat of zinc chromate primer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'After welding, stainless steel is susceptible to a corrosion known as', '[{"id": "a", "text": "weld deterioration.", "correct": false}, {"id": "b", "text": "weld decay.", "correct": true}, {"id": "c", "text": "weld rot.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The lifting or flaking of the metal at the surface due to delamination of grain boundaries caused by the pressure of corrosion is', '[{"id": "a", "text": "transgranulation.", "correct": false}, {"id": "b", "text": "electrolysis.", "correct": false}, {"id": "c", "text": "exfoliation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The electrolytic process that forms an oxide film on the surface of aluminium alloys is known as', '[{"id": "a", "text": "galvanizing.", "correct": false}, {"id": "b", "text": "anodizing.", "correct": true}, {"id": "c", "text": "electroplating.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the indication of fretting corrosion on aluminium alloy?', '[{"id": "a", "text": "Black powder.", "correct": true}, {"id": "b", "text": "Brown powder.", "correct": false}, {"id": "c", "text": "White powder.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What action is taken to protect integral tanks from corrosion due to micro-biological growth?', '[{"id": "a", "text": "The inside of the tank is coated with yellow chromate.", "correct": false}, {"id": "b", "text": "Rubber liners are installed in the tank.", "correct": false}, {"id": "c", "text": "A biocidal additive is used in the fuel.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What type of corrosion attacks grain boundaries of aluminium alloys which are improperly or inadequately heat treated?', '[{"id": "a", "text": "Stress corrosion.", "correct": false}, {"id": "b", "text": "Intergranular corrosion.", "correct": true}, {"id": "c", "text": "Surface corrosion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The artificial production of a film of oxide on the surface of aluminium or any of its alloys is commonly called', '[{"id": "a", "text": "alodizing.", "correct": false}, {"id": "b", "text": "parco lubrizing.", "correct": false}, {"id": "c", "text": "anodizing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Intergranular corrosion in structural aluminium alloy parts', '[{"id": "a", "text": "are not likely to occur in parts fabricated from heat-treated sheet aluminium.", "correct": false}, {"id": "b", "text": "may be detected by the white, powdery deposit formed on the surface of the metal.", "correct": false}, {"id": "c", "text": "cannot always be detected by surface indications.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Corrosion will spread more rapidly when metals are exposed to', '[{"id": "a", "text": "dry climates.", "correct": false}, {"id": "b", "text": "cold climates.", "correct": false}, {"id": "c", "text": "high temperatures.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Magnesium alloy components are protected by', '[{"id": "a", "text": "an electro process.", "correct": false}, {"id": "b", "text": "a chemical process.", "correct": true}, {"id": "c", "text": "a painted process.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Corrosion products should be removed from magnesium alloys by the use of', '[{"id": "a", "text": "a solution of 10% by weight of chromic acid in distilled water with 0.1% by volume of sulphuric acid.", "correct": true}, {"id": "b", "text": "a solution of 10% by volume of chromic acid in distilled water with 1% phosphoric acid.", "correct": false}, {"id": "c", "text": "aluminium wool.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'If it is necessary to remove corrosion from a steel component in-situ, the base of a suitable solution for this purpose is', '[{"id": "a", "text": "chromic acid.", "correct": false}, {"id": "b", "text": "phosphoric acid.", "correct": true}, {"id": "c", "text": "nitric acid.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A type of protection which is applicable to magnesium alloys is the', '[{"id": "a", "text": "phosphate process.", "correct": false}, {"id": "b", "text": "chromating process.", "correct": true}, {"id": "c", "text": "coslettising process.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Heavy corrosion deposits on clad aluminium alloys should be removed', '[{"id": "a", "text": "chemically by use of phosphoric acid.", "correct": false}, {"id": "b", "text": "chemically by use of trichloroethylene.", "correct": false}, {"id": "c", "text": "mechanically using a pneumatic vibrator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What action should be taken on finding intergranular corrosion?', '[{"id": "a", "text": "Replace complete component part.", "correct": true}, {"id": "b", "text": "De-corrode and reprotect.", "correct": false}, {"id": "c", "text": "Renew corroded area by patching.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Anodic treatment of aluminium alloy gives', '[{"id": "a", "text": "a purple finish.", "correct": false}, {"id": "b", "text": "a shorter life due to hardening.", "correct": false}, {"id": "c", "text": "a pure coating of aluminium oxide on the surface.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Corrosion at the grain boundaries is called', '[{"id": "a", "text": "intergranular.", "correct": true}, {"id": "b", "text": "fretting.", "correct": false}, {"id": "c", "text": "filiform.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Fretting corrosion occurs where', '[{"id": "a", "text": "two materials are subject to very slight movement between the two.", "correct": true}, {"id": "b", "text": "a deep scratch increases to become fretting corrosion.", "correct": false}, {"id": "c", "text": "pitting corrosion is allowed to become more pronounced.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is used to remove corrosion from magnesium?', '[{"id": "a", "text": "Phosphoric acid solution.", "correct": false}, {"id": "b", "text": "Chromic acid solution.", "correct": true}, {"id": "c", "text": "Sulphuric acid solution.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Surface corrosion on stainless steel is identified by', '[{"id": "a", "text": "red rust.", "correct": false}, {"id": "b", "text": "white film.", "correct": false}, {"id": "c", "text": "black pitting.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Hooks, wires and other suspension devices used in an anodic bath should be made of', '[{"id": "a", "text": "brass or copper.", "correct": false}, {"id": "b", "text": "aluminium or titanium.", "correct": true}, {"id": "c", "text": "steel or copper.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Spilled mercury on aluminium', '[{"id": "a", "text": "increases susceptibility to hydrogen embrittlement.", "correct": false}, {"id": "b", "text": "may cause impaired corrosion resistance if left in prolonged contact.", "correct": false}, {"id": "c", "text": "causes rapid and severe corrosion in prolonged contact.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Intercrystalline corrosion', '[{"id": "a", "text": "is detectable by x-rays.", "correct": true}, {"id": "b", "text": "is the same as exfoliation corrosion.", "correct": false}, {"id": "c", "text": "always appears as small surface cracks.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The usual manufacturers anti-corrosion process to be applied to Fe aircraft parts is', '[{"id": "a", "text": "cadmium plating.", "correct": true}, {"id": "b", "text": "anodising.", "correct": false}, {"id": "c", "text": "metal spraying.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Chromate treatment is applied to', '[{"id": "a", "text": "Al alloys.", "correct": false}, {"id": "b", "text": "Fe alloys.", "correct": false}, {"id": "c", "text": "magnesium alloys.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Anti-corrosion treatment used on Magnesium is', '[{"id": "a", "text": "chromating.", "correct": true}, {"id": "b", "text": "electro-plating.", "correct": false}, {"id": "c", "text": "phosphating.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Fretting corrosion occurs with', '[{"id": "a", "text": "water trapped between moving parts.", "correct": false}, {"id": "b", "text": "vibration in bolted parts.", "correct": true}, {"id": "c", "text": "improper heat treatment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Intergranular corrosion is also known as what?', '[{"id": "a", "text": "Stress corrosion.", "correct": false}, {"id": "b", "text": "Exfoliation.", "correct": true}, {"id": "c", "text": "Galvanic.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'During construction, sharp internal corners and inaccessible places should be avoided to reduce', '[{"id": "a", "text": "filiform corrosion.", "correct": false}, {"id": "b", "text": "fretting corrosion.", "correct": false}, {"id": "c", "text": "crevice corrosion.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'To check the interior of tubular members for corrosion attack', '[{"id": "a", "text": "any form of test is acceptable.", "correct": false}, {"id": "b", "text": "ultra sonic testing is necessary.", "correct": true}, {"id": "c", "text": "dye penetrant testing should be used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Anodising is a form of', '[{"id": "a", "text": "artificial protection.", "correct": true}, {"id": "b", "text": "metallic coating.", "correct": false}, {"id": "c", "text": "sacrificial protection.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The Alocrom 1200 process was designed to treat', '[{"id": "a", "text": "chromium plating.", "correct": false}, {"id": "b", "text": "small surfaces.", "correct": false}, {"id": "c", "text": "surfaces too large for dip treatment.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The artificial production of a film of oxide on the surface of aluminium or any of its alloys is commonly', '[{"id": "a", "text": "alodizing.", "correct": false}, {"id": "b", "text": "parco lubrizing.", "correct": false}, {"id": "c", "text": "anodizing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Alodizing protects alloy metal from corrosion and does what else?', '[{"id": "a", "text": "Makes a good surface for paint to adhere to.", "correct": true}, {"id": "b", "text": "Makes the surface alkaline.", "correct": false}, {"id": "c", "text": "Seals the surface from moisture.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When cleaning aircraft faying surfaces, a cause for concern is [see note]', '[{"id": "a", "text": "corrosion acting on the end faces of panels.", "correct": true}, {"id": "b", "text": "sharp corners etc trapping corrosive chemicals.", "correct": false}, {"id": "c", "text": "leaks into the fuselage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The form of corrosion most likely to cause stress concentration is', '[{"id": "a", "text": "Surface Corrosion.", "correct": false}, {"id": "b", "text": "Fretting Corrosion.", "correct": false}, {"id": "c", "text": "Pitting Corrosion.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Lead acid battery fluid has been found to be leaking on the surface of the aircraft structure. What substance would you use to neutralise the acid?', '[{"id": "a", "text": "Sulphur and lime.", "correct": false}, {"id": "b", "text": "Hot distilled water.", "correct": false}, {"id": "c", "text": "Sodium bicarbonate.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What colour is the corrosion found on the surface of aluminium alloys?', '[{"id": "a", "text": "White/Grey.", "correct": true}, {"id": "b", "text": "Green/Blue.", "correct": false}, {"id": "c", "text": "Black.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Corrosion on copper is identified by', '[{"id": "a", "text": "red/brown rust.", "correct": false}, {"id": "b", "text": "black powder.", "correct": false}, {"id": "c", "text": "green discolouration.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A composite flap panel has corrosion. What NDT method will you use to detect?', '[{"id": "a", "text": "Low voltage x-ray.", "correct": true}, {"id": "b", "text": "Coin tap test.", "correct": false}, {"id": "c", "text": "High voltage x-ray.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When examining a piece of metal through a magnifying glass, hair line cracks would indicate', '[{"id": "a", "text": "crevice corrosion.", "correct": false}, {"id": "b", "text": "intergranular corrosion.", "correct": true}, {"id": "c", "text": "surface corrosion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In the anodic film inspection and sealing test, if a good seal has been accomplished', '[{"id": "a", "text": "the dye mark will not rub off.", "correct": false}, {"id": "b", "text": "the dye mark has no importance.", "correct": false}, {"id": "c", "text": "the dye mark will rub off.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Aluminium alloy parts are often protected by the', '[{"id": "a", "text": "Alocrom plating.", "correct": false}, {"id": "b", "text": "chromium plating process.", "correct": false}, {"id": "c", "text": "Alocrom 1200 process.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Corrosion is always completely removed', '[{"id": "a", "text": "to prevent further damage.", "correct": false}, {"id": "b", "text": "to fit new parts.", "correct": false}, {"id": "c", "text": "to permit the extent of damage to be assessed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Corrosion on a copper alloy can be recognised by', '[{"id": "a", "text": "blue/green deposit.", "correct": true}, {"id": "b", "text": "white deposit.", "correct": false}, {"id": "c", "text": "grey deposit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of the following is a temporary protective measure? [see note]', '[{"id": "a", "text": "Sacrificial protection.", "correct": false}, {"id": "b", "text": "Chromating.", "correct": false}, {"id": "c", "text": "Paint finish.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which anti-corrosion chemical treatment is normally applied to aluminium alloys?', '[{"id": "a", "text": "Pure aluminium.", "correct": false}, {"id": "b", "text": "Anodising.", "correct": true}, {"id": "c", "text": "Cadmium.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Spilled mercury on aluminium causes', '[{"id": "a", "text": "greyish powder, fuzzy deposit or whiskery growth.", "correct": true}, {"id": "b", "text": "yellowish stains on surface of the metal.", "correct": false}, {"id": "c", "text": "black pits going into brown rust.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A non-electrolytic chemical treatment for aluminium alloys to increase corrosion resistance and paint bonding qualities is called', '[{"id": "a", "text": "alodizing.", "correct": true}, {"id": "b", "text": "anodizing.", "correct": false}, {"id": "c", "text": "dichromating.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of the following are acceptable to use in cleaning anodized surfaces?', '[{"id": "a", "text": "Steel wool, aluminium wool, fibre bristle brush.", "correct": false}, {"id": "b", "text": "Aluminium wool, fibre bristle brush.", "correct": true}, {"id": "c", "text": "Brass wire brush, stainless steel wire brush.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A primary cause of intergranular corrosion is', '[{"id": "a", "text": "improper heat treatment.", "correct": true}, {"id": "b", "text": "improper application of primer.", "correct": false}, {"id": "c", "text": "dissimilar metal contact.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of these materials is the most anodic?', '[{"id": "a", "text": "Magnesium.", "correct": true}, {"id": "b", "text": "Cadmium.", "correct": false}, {"id": "c", "text": "7075-T6 aluminium alloy.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of these materials is the most cathodic?', '[{"id": "a", "text": "2024 aluminium alloy.", "correct": false}, {"id": "b", "text": "Zinc.", "correct": false}, {"id": "c", "text": "Stainless steel.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Galvanic corrosion is most likely to be most rapid and severe when', '[{"id": "a", "text": "the surface area of the anodic metal is smaller than the surface area of the cathodic material.", "correct": true}, {"id": "b", "text": "the surface area of the cathodic metal and the anodic material are approximately the same.", "correct": false}, {"id": "c", "text": "the surface area of the cathodic metal is smaller than the surface area of the anodic material.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The pitch of a screw thread is', '[{"id": "a", "text": "crest to crest.", "correct": true}, {"id": "b", "text": "2 * crest to root.", "correct": false}, {"id": "c", "text": "crest to root.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A single start thread the lead is', '[{"id": "a", "text": "2 * pitch.", "correct": false}, {"id": "b", "text": "1 * pitch.", "correct": true}, {"id": "c", "text": "½ * pitch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A wire thread insert tap is', '[{"id": "a", "text": "supplied in a fitting kit.", "correct": false}, {"id": "b", "text": "slightly larger than the hole.", "correct": true}, {"id": "c", "text": "slightly smaller than the hole.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Multi-start threads', '[{"id": "a", "text": "increase the lead and decrease the pitch.", "correct": false}, {"id": "b", "text": "increase the lead without increasing the pitch.", "correct": true}, {"id": "c", "text": "increase the lead and the pitch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Buttress threads are used', '[{"id": "a", "text": "to transmit power in both directions.", "correct": false}, {"id": "b", "text": "to transmit power in one direction.", "correct": true}, {"id": "c", "text": "on nuts and bolts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The lead on a single start thread is', '[{"id": "a", "text": "1 * the pitch.", "correct": true}, {"id": "b", "text": "2 * the pitch.", "correct": false}, {"id": "c", "text": "1/2 the pitch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Colour identification of an aluminium rivet is', '[{"id": "a", "text": "black.", "correct": true}, {"id": "b", "text": "violet.", "correct": false}, {"id": "c", "text": "green.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'For a wire insert thread repair, the hole is tapped using', '[{"id": "a", "text": "the same size.", "correct": false}, {"id": "b", "text": "a special tap supplied with the kit.", "correct": true}, {"id": "c", "text": "the next size up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Most commonly used thread form in aviation is', '[{"id": "a", "text": "V thread.", "correct": true}, {"id": "b", "text": "round thread.", "correct": false}, {"id": "c", "text": "buttress.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Pitch of a screw thread is defined as', '[{"id": "a", "text": "distance from the centre of one crest to the next.", "correct": true}, {"id": "b", "text": "difference between major diameter and minor diameter.", "correct": false}, {"id": "c", "text": "distance between the crest and the root of the thread.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The angle of a screw thread is', '[{"id": "a", "text": "half the inclusive angle of the thread sides.", "correct": false}, {"id": "b", "text": "the inclusive angle of the thread sides.", "correct": true}, {"id": "c", "text": "the distance the thread moves in one turn.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The tang of a thread insert', '[{"id": "a", "text": "may be left in the insert after installation.", "correct": false}, {"id": "b", "text": "is removed with a hammer and a punch.", "correct": false}, {"id": "c", "text": "must be removed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A thread insert may be removed by', '[{"id": "a", "text": "a blade removal tool.", "correct": true}, {"id": "b", "text": "a hammer and punch.", "correct": false}, {"id": "c", "text": "a pre-wind insertion tool.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A metric screw thread angle is', '[{"id": "a", "text": "47.5 °.", "correct": false}, {"id": "b", "text": "55 °.", "correct": false}, {"id": "c", "text": "60 °.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which thread type has the better vibration resistance?', '[{"id": "a", "text": "A fine thread.", "correct": true}, {"id": "b", "text": "A coarse thread.", "correct": false}, {"id": "c", "text": "Coarseness or fineness of thread has no bearing on the vibration resistance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of the following thread designations is most fatigue resistant?', '[{"id": "a", "text": "UNF.", "correct": false}, {"id": "b", "text": "UNC.", "correct": false}, {"id": "c", "text": "UNJF.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which thread type has a 55 ° angle?', '[{"id": "a", "text": "Metric.", "correct": false}, {"id": "b", "text": "Whitworth.", "correct": true}, {"id": "c", "text": "UNF.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When fitting Hi-Loks [see note]', '[{"id": "a", "text": "they should be lubricated.", "correct": true}, {"id": "b", "text": "each Hi-Lok should be torqued to an individually calculated value.", "correct": false}, {"id": "c", "text": "the hole should be drilled so that it is an interference fit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What sort of surface treatment would you find on a magnesium casting?', '[{"id": "a", "text": "Anodizing.", "correct": false}, {"id": "b", "text": "Phosphating.", "correct": false}, {"id": "c", "text": "Chromating.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the nominal length of a UNF bolt?', '[{"id": "a", "text": "Under head to end of the threads.", "correct": true}, {"id": "b", "text": "Under head to screw threads (i.e. plain shank).", "correct": false}, {"id": "c", "text": "The length of the threads.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Where should you not use a nyloc nut?', '[{"id": "a", "text": "Temperatures above 120 °C.", "correct": true}, {"id": "b", "text": "Temperatures above 200 °C.", "correct": false}, {"id": "c", "text": "Temperatures above 250 °C.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the nominal screw length?', '[{"id": "a", "text": "The overall length of a countersunk screw and the non-threaded portion of a bolt.", "correct": true}, {"id": "b", "text": "The overall length of a bolt (from under the head) and the overall length of a screw (including the head).", "correct": false}, {"id": "c", "text": "The length of thread for a bolt, overall length for a countersunk screw.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A blind fastener described as external sleeve and internally threaded would be', '[{"id": "a", "text": "a cherry lock.", "correct": false}, {"id": "b", "text": "a rivnut.", "correct": true}, {"id": "c", "text": "a jo bolt.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'An aluminium alloy bolt may be identified by', '[{"id": "a", "text": "its colour (dyed black).", "correct": false}, {"id": "b", "text": "the letter A stamped on the head.", "correct": false}, {"id": "c", "text": "its colour (dyed green).", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The head marking on a close tolerance BSF bolt is [see note]', '[{"id": "a", "text": "a series of dots on the head face.", "correct": false}, {"id": "b", "text": "a raised disk on the head face.", "correct": true}, {"id": "c", "text": "a lowered ring under the hexagon.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Capped nuts are used so', '[{"id": "a", "text": "to prevent leaks from pipe ends.", "correct": true}, {"id": "b", "text": "the part is not over torqued as the bolt touches the captive part first.", "correct": false}, {"id": "c", "text": "to ensure that it is dry bolted.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A bolt part number AN25C15 when compared to a bolt part number AN25-15 has', '[{"id": "a", "text": "a less expensive design and product costs.", "correct": false}, {"id": "b", "text": "a higher resistance to corrosion.", "correct": true}, {"id": "c", "text": "a higher pitch thread.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The initials U.N.C when related to aircraft bolts stands for', '[{"id": "a", "text": "United National Countersunk.", "correct": false}, {"id": "b", "text": "Unified National Coarse.", "correct": true}, {"id": "c", "text": "Unified National Centred.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Dzus Fasteners provide', '[{"id": "a", "text": "quick release fasteners at inspection panels.", "correct": true}, {"id": "b", "text": "a close tolerance fit.", "correct": false}, {"id": "c", "text": "for easy hammering into position.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A dowel will take what loads?', '[{"id": "a", "text": "torsion.", "correct": false}, {"id": "b", "text": "shear.", "correct": true}, {"id": "c", "text": "tensile.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A bolt with a raised dash is', '[{"id": "a", "text": "Corrosion Resistant Steel.", "correct": false}, {"id": "b", "text": "close tolerance.", "correct": false}, {"id": "c", "text": "AN standard.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Studs which have a size larger thread at one end are called', '[{"id": "a", "text": "plain studs.", "correct": false}, {"id": "b", "text": "shouldered studs.", "correct": false}, {"id": "c", "text": "stepped studs.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A (British) 3/8 inch dia. UNF bolt will have the diameter code letter [see note]', '[{"id": "a", "text": "N.", "correct": false}, {"id": "b", "text": "G.", "correct": true}, {"id": "c", "text": "J.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'An AN steel bolt is identified by', '[{"id": "a", "text": "plain bolt.", "correct": false}, {"id": "b", "text": "X on head.", "correct": true}, {"id": "c", "text": "dash on head.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Rivnuts were originally used for', '[{"id": "a", "text": "securing structural parts.", "correct": false}, {"id": "b", "text": "securing rubber de-icing boots.", "correct": true}, {"id": "c", "text": "securing cabin flooring.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Fork end fittings on control rod ends should have', '[{"id": "a", "text": "anti vibration compound.", "correct": false}, {"id": "b", "text": "0.002 inch axial movement.", "correct": true}, {"id": "c", "text": "bolt heads fitted upwards.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The AN526 truss-head screw', '[{"id": "a", "text": "provides a good clamping force.", "correct": false}, {"id": "b", "text": "is a widely used recessed head machine screw.", "correct": true}, {"id": "c", "text": "is a pan-head screw.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Capped nuts are used', '[{"id": "a", "text": "prevent overtightening due to the threaded portion being restricted by the cap.", "correct": false}, {"id": "b", "text": "to provide a dry torque joint.", "correct": false}, {"id": "c", "text": "to stop leaks.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A pin in a fork end fitting is subjected to what loading?', '[{"id": "a", "text": "Shear.", "correct": true}, {"id": "b", "text": "Tensile.", "correct": false}, {"id": "c", "text": "Torsion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Hi-Loks', '[{"id": "a", "text": "require lubrication of the screw part only.", "correct": false}, {"id": "b", "text": "are pre-lubricated.", "correct": true}, {"id": "c", "text": "do not require lubrication.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'UNF means', '[{"id": "a", "text": "unified fine.", "correct": true}, {"id": "b", "text": "union national fine.", "correct": false}, {"id": "c", "text": "united nations fine.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A clevis bolt in a control cable fork end would be loaded in', '[{"id": "a", "text": "shear.", "correct": true}, {"id": "b", "text": "tension.", "correct": false}, {"id": "c", "text": "both tension and shear.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Capped nuts are used', '[{"id": "a", "text": "to provide dry bolting of the joints.", "correct": false}, {"id": "b", "text": "to lock the nut to the bolt.", "correct": false}, {"id": "c", "text": "to stop leaks due to metal caps fitted on the heads.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A main difference between Lockbolt/Hucbolt tension and shear fasteners (other than their application) is in the', '[{"id": "a", "text": "shape of the head.", "correct": false}, {"id": "b", "text": "method of installation.", "correct": false}, {"id": "c", "text": "number of locking collar grooves.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'One of the main advantages of the Hi-Lok type fasteners over earlier generations is that', '[{"id": "a", "text": "they can be installed with ordinary hand-tools.", "correct": true}, {"id": "b", "text": "they can be removed and reused again.", "correct": false}, {"id": "c", "text": "the squeezed on collar installation provides a more secure, tighter fit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The markings on the head of a Dzus fastener identify the', '[{"id": "a", "text": "body diameter, type of head and length of the fastener.", "correct": true}, {"id": "b", "text": "body type, head diameter and type of material.", "correct": false}, {"id": "c", "text": "manufacturer and type of material.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The Dzus turnlock fastener consists of a stud, grommet, and receptacle. The stud length is measured in', '[{"id": "a", "text": "sixteenths of an inch.", "correct": false}, {"id": "b", "text": "tenths of an inch.", "correct": false}, {"id": "c", "text": "hundredths of an inch.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Threaded rivets (Rivnuts) are commonly used to', '[{"id": "a", "text": "join two or more pieces of sheet metal where shear strength is desired.", "correct": false}, {"id": "b", "text": "attach parts or components with screws to sheet metal.", "correct": true}, {"id": "c", "text": "join two or more pieces of sheet metal where bearing strength is desired.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Aircraft bolts with a cross or asterisk marked on the bolt-head are', '[{"id": "a", "text": "made of aluminium alloy.", "correct": false}, {"id": "b", "text": "a standard steel bolt.", "correct": true}, {"id": "c", "text": "close tolerance bolts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A bolt with a single dash on the head is classified as an', '[{"id": "a", "text": "NAS standard aircraft bolt.", "correct": true}, {"id": "b", "text": "AN corrosion resistant steel bolt.", "correct": false}, {"id": "c", "text": "NAS close tolerance bolt.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Aircraft bolts are usually manufactured with a', '[{"id": "a", "text": "class 1 fit for the threads.", "correct": false}, {"id": "b", "text": "class 2 fit for the threads.", "correct": false}, {"id": "c", "text": "class 3 fit for the threads.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The cage of an Instrument Mounting nut is made from', '[{"id": "a", "text": "steel.", "correct": false}, {"id": "b", "text": "brass.", "correct": true}, {"id": "c", "text": "phosphor bronze.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The speed nut of an Instrument Mounting nut is made from', '[{"id": "a", "text": "brass.", "correct": false}, {"id": "b", "text": "steel.", "correct": false}, {"id": "c", "text": "phosphor bronze.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Instrument Mounting nuts are', '[{"id": "a", "text": "soldered in place during manufacture.", "correct": false}, {"id": "b", "text": "prevented from dropping behind the instrument panel by magnetism.", "correct": false}, {"id": "c", "text": "non-magnetic.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The length of a clevis bolt', '[{"id": "a", "text": "includes the head and the thread.", "correct": false}, {"id": "b", "text": "is the plain shank portion only.", "correct": false}, {"id": "c", "text": "includes the threads but not the head.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How many times can a locking plate be used?', '[{"id": "a", "text": "indefinitely providing it is a good fit around the component to be locked.", "correct": true}, {"id": "b", "text": "once, then discarded.", "correct": false}, {"id": "c", "text": "3 times, then discarded.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The taper of a standard taper pin is', '[{"id": "a", "text": "1 in 48.", "correct": true}, {"id": "b", "text": "1 in 36.", "correct": false}, {"id": "c", "text": "1 in 20.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When using a spring washer, the plain washer would be fitted', '[{"id": "a", "text": "between spring and part.", "correct": true}, {"id": "b", "text": "between head and spring.", "correct": false}, {"id": "c", "text": "under the nut.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How many times can you use a locking plate?', '[{"id": "a", "text": "Until all the tabs have been broken off.", "correct": false}, {"id": "b", "text": "As long as it remains serviceable.", "correct": true}, {"id": "c", "text": "Once only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Wire locking approach angles should not be less than', '[{"id": "a", "text": "45 °.", "correct": true}, {"id": "b", "text": "90 °.", "correct": false}, {"id": "c", "text": "10 °.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A spring type washer when used on an aluminium component must be used', '[{"id": "a", "text": "with a plain washer.", "correct": true}, {"id": "b", "text": "by itself.", "correct": false}, {"id": "c", "text": "with a tab washer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Nickel alloy steel split pins can be used', '[{"id": "a", "text": "repeatedly provided they remain a good fit.", "correct": false}, {"id": "b", "text": "only once, because the legs are spread and bent.", "correct": true}, {"id": "c", "text": "with a spring washer and a stiff nut.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A pre-load indicating washer is correctly loaded when', '[{"id": "a", "text": "the inner ring rotates.", "correct": false}, {"id": "b", "text": "the inner ring is gripped.", "correct": true}, {"id": "c", "text": "the outer ring is gripped.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The advantage of circlips is', '[{"id": "a", "text": "it can be used for both internal and external applications.", "correct": false}, {"id": "b", "text": "it is cheap.", "correct": false}, {"id": "c", "text": "both of the above.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A press fit requires', '[{"id": "a", "text": "the hole to be expanded by heat.", "correct": false}, {"id": "b", "text": "some sort of driving force.", "correct": true}, {"id": "c", "text": "the shaft to be shrunk by cooling.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A non metallic locknut is', '[{"id": "a", "text": "never used over 250 °F.", "correct": true}, {"id": "b", "text": "never torqued.", "correct": false}, {"id": "c", "text": "never re-used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which can be re-used?', '[{"id": "a", "text": "Locking plate, circlip, spring washer.", "correct": true}, {"id": "b", "text": "Shake proof washer, spring washer, locking plate.", "correct": false}, {"id": "c", "text": "Tab washer, circlip, locking plate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A tab washer has been removed after fitment for a short time from a non essential system, the tab washer may be', '[{"id": "a", "text": "re-used.", "correct": false}, {"id": "b", "text": "re-used if a spare is not available.", "correct": false}, {"id": "c", "text": "not re-used.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Taper pins are subject to what loads?', '[{"id": "a", "text": "Tensile.", "correct": false}, {"id": "b", "text": "Compressive.", "correct": false}, {"id": "c", "text": "Shear.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A turnbuckle locknut is a', '[{"id": "a", "text": "stiff nut.", "correct": true}, {"id": "b", "text": "slotted nut.", "correct": false}, {"id": "c", "text": "castle nut.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A spring washer', '[{"id": "a", "text": "may be used a second time provided it is fitted the reverse way round.", "correct": false}, {"id": "b", "text": "may be used more than once provided it continues to provide an efficient lock.", "correct": true}, {"id": "c", "text": "must not be used more than once.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'An internal circlip can be used to', '[{"id": "a", "text": "retain a ball bearing in a housing.", "correct": true}, {"id": "b", "text": "to do both of the above.", "correct": false}, {"id": "c", "text": "retain a ball bearing on a shaft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A washer having both twisted teeth and spring actions is', '[{"id": "a", "text": "AN970 large-area flat washer.", "correct": false}, {"id": "b", "text": "AN936 shake-proof lock washer.", "correct": true}, {"id": "c", "text": "AN935 split-ring lock washer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Split pins', '[{"id": "a", "text": "may be used only once.", "correct": true}, {"id": "b", "text": "can be used more than once but depends on the material of the split pin.", "correct": false}, {"id": "c", "text": "may be used more than once.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How is the locking feature of the fibre-type locknut obtained?', '[{"id": "a", "text": "By a fibre insert held firmly in place at the base of the load carrying section.", "correct": false}, {"id": "b", "text": "By the use of an unthreaded fibre locking insert.", "correct": true}, {"id": "c", "text": "By making the threads in the fibre insert slightly smaller than those in the load carrying section.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Split pins are made from', '[{"id": "a", "text": "brass or Low carbon steel - cadmium plated.", "correct": false}, {"id": "b", "text": "brass or stainless steel.", "correct": false}, {"id": "c", "text": "Low carbon steel - cadmium plated, or stainless steel.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Forming a solution treated rivet gives it 75% of its hardness. What gives it the other 25%?', '[{"id": "a", "text": "Leave at room temperature for four hours.", "correct": true}, {"id": "b", "text": "Precipitation treat the component when forming is complete.", "correct": false}, {"id": "c", "text": "Put them in a refrigerator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'If D or DD rivets are not formed in time, or removed from the freezer in time, they', '[{"id": "a", "text": "must be discarded.", "correct": false}, {"id": "b", "text": "must be re-heat treated before use.", "correct": true}, {"id": "c", "text": "can be re-heat treated once then discarded.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A joggle in a removed rivet is indication of what type of partial failure?', '[{"id": "a", "text": "Bearing.", "correct": false}, {"id": "b", "text": "Shear.", "correct": true}, {"id": "c", "text": "Compression.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How is a British aluminium rivet identified?', '[{"id": "a", "text": "Black anodic finish.", "correct": true}, {"id": "b", "text": "Natural anodised finish.", "correct": false}, {"id": "c", "text": "Violet anodic finish.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What do the letters and numbers on a British rivet mean?', '[{"id": "a", "text": "Material specification only.", "correct": false}, {"id": "b", "text": "Material and finish.", "correct": false}, {"id": "c", "text": "Head shape, material and finish.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A natural finish aluminium alloy rivet with a D on it is', '[{"id": "a", "text": "hiduminium L86.", "correct": false}, {"id": "b", "text": "aluminium L36.", "correct": false}, {"id": "c", "text": "duralumin L37.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What metal is suitable for riveting magnesium alloy?', '[{"id": "a", "text": "1100 aluminium alloy.", "correct": false}, {"id": "b", "text": "5056 aluminium alloy.", "correct": true}, {"id": "c", "text": "Monel metal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What metal is suitable for riveting alloy steel?', '[{"id": "a", "text": "Aluminium alloy.", "correct": false}, {"id": "b", "text": "Monel metal.", "correct": true}, {"id": "c", "text": "Mild steel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'An aluminium alloy L37 rivet identification is', '[{"id": "a", "text": "X embossed.", "correct": false}, {"id": "b", "text": "O embossed.", "correct": false}, {"id": "c", "text": "D embossed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Rivet allowance is', '[{"id": "a", "text": "1.5d.", "correct": true}, {"id": "b", "text": "1d plus the thickness of the material.", "correct": false}, {"id": "c", "text": "1.5d plus the thickness of the material.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'D and DD rivets are refrigerated to', '[{"id": "a", "text": "precipitation harden.", "correct": false}, {"id": "b", "text": "increase age hardening.", "correct": false}, {"id": "c", "text": "retard age hardening.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What do you do to 2017 and 2024 rivets after heat treatment?', '[{"id": "a", "text": "Leave for a minimum of 2 hours before using.", "correct": false}, {"id": "b", "text": "refrigerate for a minimum of 2 hours before using.", "correct": false}, {"id": "c", "text": "Use immediately or refrigerate.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'An American rivet with a cross on the head is', '[{"id": "a", "text": "2124 aluminium alloy.", "correct": false}, {"id": "b", "text": "2117 aluminium alloy.", "correct": false}, {"id": "c", "text": "5056 aluminium alloy.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A countersunk rivet of the ‘SP’ series has a head style of [see note]', '[{"id": "a", "text": "20 °.", "correct": false}, {"id": "b", "text": "90 °.", "correct": true}, {"id": "c", "text": "100 °.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The coding of a British rivet indicates', '[{"id": "a", "text": "length and diameter.", "correct": false}, {"id": "b", "text": "head type and colour.", "correct": false}, {"id": "c", "text": "material and head type.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A factor which determines the minimum space between rivets is the', '[{"id": "a", "text": "thickness of the material being riveted.", "correct": false}, {"id": "b", "text": "diameter of the rivets being used.", "correct": true}, {"id": "c", "text": "length of the rivets being used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Joggles in removed rivet shanks would indicate partial', '[{"id": "a", "text": "torsion failure.", "correct": false}, {"id": "b", "text": "shear failure.", "correct": true}, {"id": "c", "text": "bearing failure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A rivet that has 5% magnesium is identified as', '[{"id": "a", "text": "anodic violet and has an X.", "correct": true}, {"id": "b", "text": "anodic green and has an X.", "correct": false}, {"id": "c", "text": "natural and has an m.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Identification of British aluminium alloy rivets is with', '[{"id": "a", "text": "a part number on the head.", "correct": false}, {"id": "b", "text": "a letter and number code.", "correct": true}, {"id": "c", "text": "a colour and number stamped on the head.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'If you can only gain limited access to both sides of a structure, what would you use to repair the structure?', '[{"id": "a", "text": "Hi-Lok.", "correct": false}, {"id": "b", "text": "blind rivet.", "correct": true}, {"id": "c", "text": "pop rivet.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Alloy rivets are heat treated by', '[{"id": "a", "text": "solution treating.", "correct": true}, {"id": "b", "text": "annealing.", "correct": false}, {"id": "c", "text": "anodising.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When a solid rivet is formed it only holds 75% of its shear strength, the other 25% comes from', '[{"id": "a", "text": "leaving assembly for 4 days to age harden.", "correct": true}, {"id": "b", "text": "heating the completed assembly.", "correct": false}, {"id": "c", "text": "cooling completed assembly.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A rivet with no marking has the material code', '[{"id": "a", "text": "AD.", "correct": false}, {"id": "b", "text": "A.", "correct": true}, {"id": "c", "text": "D.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Rivet MS20426 has what head type?', '[{"id": "a", "text": "CSK.", "correct": true}, {"id": "b", "text": "Universal.", "correct": false}, {"id": "c", "text": "Round.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is meant by the term Pitch Ratio?', '[{"id": "a", "text": "The area of contact between the two sheets of metal when joining by rivets.", "correct": false}, {"id": "b", "text": "The distance between the hole and the edge of the material.", "correct": false}, {"id": "c", "text": "The distance between two holes.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The length of solid rivets is in graduations of', '[{"id": "a", "text": "1/16 inch.", "correct": true}, {"id": "b", "text": "1/8 inch.", "correct": false}, {"id": "c", "text": "1/4 inch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What would be the diameter and length of a solid rivet if the following markings are given, AS 162-408?', '[{"id": "a", "text": "¼ inch dia, ½ inch length.", "correct": false}, {"id": "b", "text": "½ inch dia, 1 inch length.", "correct": false}, {"id": "c", "text": "1/8 inch dia, ½ inch length.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What would the marking .5 indicate after the normal part number of a solid rivet? [see note]', '[{"id": "a", "text": "The rivet length in graduations of 1/8 inch.", "correct": true}, {"id": "b", "text": "The diameter of the rivet is half an inch.", "correct": false}, {"id": "c", "text": "Indicates close tolerance rivet.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the pressure range for the Avdel Riveter type F? [see note]', '[{"id": "a", "text": "60 to 80 psi.", "correct": true}, {"id": "b", "text": "20 to 60 psi.", "correct": false}, {"id": "c", "text": "40 to 60 psi.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the length of the operation stroke of the Avdel Riveter type F? [see note]', '[{"id": "a", "text": "½ inch.", "correct": false}, {"id": "b", "text": "7/8 inch.", "correct": true}, {"id": "c", "text": "1 inch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'If a sheet of aluminium alloy of 0.032 and 0.064 is to be joined together the rivet should be', '[{"id": "a", "text": "0.032 plus 2D.", "correct": false}, {"id": "b", "text": "0.096 plus 1.5 D.", "correct": true}, {"id": "c", "text": "0.064 plus 1D.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Where would a pop rivet with a break stem mandrel be used?', '[{"id": "a", "text": "In a closed structure.", "correct": false}, {"id": "b", "text": "Where the head can be retrieved.", "correct": true}, {"id": "c", "text": "Any situation calling for a pop rivet.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A Chobert rivet gun may be used', '[{"id": "a", "text": "until the end has worn 0.002 inch below nominal diameter.", "correct": true}, {"id": "b", "text": "indefinitely.", "correct": false}, {"id": "c", "text": "once only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Avdel rivets are closed by', '[{"id": "a", "text": "a tapered mandrel.", "correct": true}, {"id": "b", "text": "broaching.", "correct": false}, {"id": "c", "text": "squeezing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Countersunk rivets have two angles of countersink, these are', '[{"id": "a", "text": "100 and 120 degrees.", "correct": true}, {"id": "b", "text": "125 and 135 degrees.", "correct": false}, {"id": "c", "text": "100 and 160 degrees.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'On a CherryMAX rivet, after the riveting process the mandrel section or stem', '[{"id": "a", "text": "is ground down flush with the rivet head.", "correct": false}, {"id": "b", "text": "is discarded.", "correct": false}, {"id": "c", "text": "remains in the rivet sleeve to provide mechanical strength.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'On a structural repair, what type of rivet would you use when the back side cannot be accessed?', '[{"id": "a", "text": "Pop rivet.", "correct": false}, {"id": "b", "text": "Hi-Lok rivet.", "correct": false}, {"id": "c", "text": "Blind rivet.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What material is suitable for riveting steel?', '[{"id": "a", "text": "Aluminium alloy.", "correct": false}, {"id": "b", "text": "Monel.", "correct": true}, {"id": "c", "text": "Copper.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Cadmium plated rivets should not be used where the temperature may exceed', '[{"id": "a", "text": "120 °C.", "correct": false}, {"id": "b", "text": "250 °C.", "correct": true}, {"id": "c", "text": "200 °C.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What rivets should be used with nickel alloy steel?', '[{"id": "a", "text": "Aluminium Alloy.", "correct": false}, {"id": "b", "text": "Mild Steel.", "correct": false}, {"id": "c", "text": "Monel.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is an advantage of a double flare on aluminium tubing?', '[{"id": "a", "text": "Ease of construction.", "correct": false}, {"id": "b", "text": "It is more resistant to the shearing effect of torque.", "correct": true}, {"id": "c", "text": "It is less resistant to the shearing effect of torque.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What type loads cause the most rivet failures?', '[{"id": "a", "text": "Bearing.", "correct": false}, {"id": "b", "text": "Shear.", "correct": true}, {"id": "c", "text": "Head.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A plate 10 inches by 5 inches is to be riveted with 3 rows of rivets, with the normal 4D rivet spacing and 2D edge distance. The rivets are AN470AD4-6. How many rivets are required?', '[{"id": "a", "text": "60.", "correct": true}, {"id": "b", "text": "52.", "correct": false}, {"id": "c", "text": "56.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What type of heat treatment can be used on DD rivets?', '[{"id": "a", "text": "Annealing.", "correct": false}, {"id": "b", "text": "Precipitation.", "correct": false}, {"id": "c", "text": "Solution Treatment.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The general rule for finding the proper rivet diameter is', '[{"id": "a", "text": "three times the thickness of the thickest sheet.", "correct": true}, {"id": "b", "text": "three times the thickness of the material to be joined.", "correct": false}, {"id": "c", "text": "two times the rivet length.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Cherrymax and Olympic-Lok rivets', '[{"id": "a", "text": "utilize a rivet gun, special rivet set, and bucking bar for installation.", "correct": false}, {"id": "b", "text": "may be installed with ordinary hand tools.", "correct": false}, {"id": "c", "text": "utilize a pulling tool for installation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Hole filling fasteners (for example, MS20470 rivets) should not be used in composite structures primarily because of the', '[{"id": "a", "text": "increased possibility of fretting corrosion in the fastener.", "correct": false}, {"id": "b", "text": "difficulty in forming a proper shop head.", "correct": false}, {"id": "c", "text": "possibility of causing delamination.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The dimensions of an MS20430AD-4-8 rivet are', '[{"id": "a", "text": "1/8 inch in diameter and 1/4 inch long.", "correct": false}, {"id": "b", "text": "4/16 inch in diameter and 8/32 inch long.", "correct": false}, {"id": "c", "text": "1/8 inch in diameter and 1/2 inch long.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The primary alloying agent of 2024-T36 rivets is indicated by the number', '[{"id": "a", "text": "20.", "correct": false}, {"id": "b", "text": "2.", "correct": true}, {"id": "c", "text": "24.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Most rivets used in aircraft construction have', '[{"id": "a", "text": "a raised dot.", "correct": false}, {"id": "b", "text": "dimples.", "correct": true}, {"id": "c", "text": "smooth heads without markings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'MS20426AD-6-5 indicates a countersunk rivet which has', '[{"id": "a", "text": "a shank length of 5/16 inch (excluding head).", "correct": true}, {"id": "b", "text": "an overall length of 5/16 inch.", "correct": false}, {"id": "c", "text": "a shank length of 5/32 inch (excluding head).", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which rivet may be used as received without further treatment?', '[{"id": "a", "text": "2017-T3.", "correct": false}, {"id": "b", "text": "2117-T3.", "correct": true}, {"id": "c", "text": "2024-T4.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The information on rivet grip length is in which rivet code quadrant? [see note]', '[{"id": "a", "text": "NW.", "correct": false}, {"id": "b", "text": "SE.", "correct": true}, {"id": "c", "text": "NE.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The NE rivet quadrant gives information on [see note]', '[{"id": "a", "text": "diameter and manufactured head location.", "correct": true}, {"id": "b", "text": "fastener identity.", "correct": false}, {"id": "c", "text": "head data.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A square around the NW digit in the quadrant of a fastener would indicate', '[{"id": "a", "text": "interference fit fastener.", "correct": true}, {"id": "b", "text": "Hi-Lok to be used.", "correct": false}, {"id": "c", "text": "fluid tight fastener.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The four quadrants on a quadrant rivet code system are designated', '[{"id": "a", "text": "N, S, E, W.", "correct": false}, {"id": "b", "text": "top-left, top-right, bottom-left, bottom-right.", "correct": false}, {"id": "c", "text": "NW, NE, SE, SW.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When replacing a hydraulic pipe, where would you find the correct replacement part?', '[{"id": "a", "text": "Parts catalogue.", "correct": true}, {"id": "b", "text": "Maintenance schedule.", "correct": false}, {"id": "c", "text": "Maintenance manual.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How are flexible hoses categorised?', '[{"id": "a", "text": "By maximum pressure.", "correct": true}, {"id": "b", "text": "By diameter.", "correct": false}, {"id": "c", "text": "By length.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What are the rigid pipes on gas turbine engines made from?', '[{"id": "a", "text": "Stainless steel.", "correct": true}, {"id": "b", "text": "Aluminium alloy.", "correct": false}, {"id": "c", "text": "Copper.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How would you test a hydraulic hose?', '[{"id": "a", "text": "Pressure test 2.0 * working pressure.", "correct": true}, {"id": "b", "text": "Pressure test 1.5 * working pressure.", "correct": false}, {"id": "c", "text": "Pressure test 1.0 * working pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'To prevent damage to seals on fitment you would', '[{"id": "a", "text": "compress and stretch them.", "correct": false}, {"id": "b", "text": "use a cardboard protector over the threaded portions.", "correct": true}, {"id": "c", "text": "use grease.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A pipe carrying lubricant would be identified by the colour', '[{"id": "a", "text": "white.", "correct": false}, {"id": "b", "text": "yellow.", "correct": true}, {"id": "c", "text": "white and yellow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which material is a hydraulic fluid hose made from?', '[{"id": "a", "text": "Rubber.", "correct": false}, {"id": "b", "text": "Butyl.", "correct": false}, {"id": "c", "text": "Teflon.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Hydraulic pipes are made from', '[{"id": "a", "text": "5052-O or 2024-T aluminium alloy.", "correct": true}, {"id": "b", "text": "1100 or 3003 H14 aluminium alloy.", "correct": false}, {"id": "c", "text": "5056 or 7075 aluminium alloy.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The continuous coloured line on a hose assembly', '[{"id": "a", "text": "identifies hose material.", "correct": false}, {"id": "b", "text": "will assist in detection of any twist in an installed hose.", "correct": true}, {"id": "c", "text": "identifies fluid compatibility of hose.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The storage life of a flexible hose can be up to but not exceeding [see note]', '[{"id": "a", "text": "5 years.", "correct": false}, {"id": "b", "text": "2 years.", "correct": false}, {"id": "c", "text": "4 years.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The markings on a flexible hose must include the', '[{"id": "a", "text": "internal bore size.", "correct": false}, {"id": "b", "text": "manufacturers name.", "correct": false}, {"id": "c", "text": "date of manufacture.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'MIL-H-5606 hydraulic fluid O-rings are identified with a', '[{"id": "a", "text": "blue dot.", "correct": true}, {"id": "b", "text": "yellow dot.", "correct": false}, {"id": "c", "text": "yellow and white dot.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What type of material would hydraulic pipes on an undercarriage leg or bay be made from?', '[{"id": "a", "text": "Stainless steel, annealed, 1/4H.", "correct": true}, {"id": "b", "text": "7075, H14.", "correct": false}, {"id": "c", "text": "1100 or 2024, in the half hard state.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A metal pipe has a small indentation. What are the limits?', '[{"id": "a", "text": "5% internal diameter.", "correct": false}, {"id": "b", "text": "10% of external diameter.", "correct": false}, {"id": "c", "text": "No dent on a bend.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'An aircraft pipe has a number stamped on it. It is the', '[{"id": "a", "text": "fluid it is carrying.", "correct": false}, {"id": "b", "text": "aircraft system.", "correct": false}, {"id": "c", "text": "serial number.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The length of a straight hose assembly is measured', '[{"id": "a", "text": "between the outer faces of the union nuts.", "correct": true}, {"id": "b", "text": "between the extremities of the two nipples.", "correct": false}, {"id": "c", "text": "along the coloured line.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Metal tubing fluid lines are sized by wall thickness and', '[{"id": "a", "text": "outside diameter and 1/32 inch increments.", "correct": false}, {"id": "b", "text": "inside diameter and 1/16 inch increments.", "correct": false}, {"id": "c", "text": "outside diameter and 1/16 inch increments.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A certain amount of slack must be left in a flexible hose during installation because, when under pressure, it', '[{"id": "a", "text": "expands in length and contracts in diameter.", "correct": false}, {"id": "b", "text": "contracts in length and expands in diameter.", "correct": true}, {"id": "c", "text": "expands in length and diameter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Flexible lines must be fitted with a slack', '[{"id": "a", "text": "of 5 - 8 % of the length.", "correct": true}, {"id": "b", "text": "of at least 10 - 12 % of the length.", "correct": false}, {"id": "c", "text": "to allow maximum flexing during operation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The material specifications for a certain aircraft require that a replacement oil line be fabricated from 3/4 inch, 0.072 wall, 5052-O aluminium alloy tubing. What is the inside diameter of this tubing?', '[{"id": "a", "text": "0.688 inch.", "correct": false}, {"id": "b", "text": "0.606 inch.", "correct": true}, {"id": "c", "text": "0.750 inch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Excessive stress on fluid or pneumatic metal tubing caused by expansion and contraction due to temperature changes can best be avoided by', '[{"id": "a", "text": "providing bends in the tubing.", "correct": true}, {"id": "b", "text": "using short, straight sections of tubing between fixed parts of the structure of the aircraft.", "correct": false}, {"id": "c", "text": "not subjecting the aircraft to sudden changes in temperature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Flexible hose used in aircraft systems is classified in size according to the', '[{"id": "a", "text": "outside diameter.", "correct": false}, {"id": "b", "text": "inside diameter.", "correct": true}, {"id": "c", "text": "wall thickness.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which tubings have the characteristics (high strength, abrasion resistance) necessary for use in a high pressure (3,000 PSI) hydraulic system for operation of landing gear and flaps?', '[{"id": "a", "text": "1100-1/2H or 3003-1/2H aluminium alloy.", "correct": false}, {"id": "b", "text": "Corrosion resistant steel annealed 1/4H.", "correct": true}, {"id": "c", "text": "2024-T or 5052-0 aluminium alloy.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A gas or fluid line marked with the letters PHDAN', '[{"id": "a", "text": "is a high pressure line. The letters mean Pressure High, Discharge at Nacelle.", "correct": false}, {"id": "b", "text": "is carrying a substance which may be dangerous to personnel.", "correct": true}, {"id": "c", "text": "is carrying a substance which cannot be made non-toxic.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A 3/8 inch aircraft high pressure flexible hose compared to a 3/8 inch metal tubing used in the same system will [see note]', '[{"id": "a", "text": "have equivalent flow characteristics.", "correct": false}, {"id": "b", "text": "have about the same OD.", "correct": false}, {"id": "c", "text": "usually have interchangeable applications.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How do you assemble a banjo hose?', '[{"id": "a", "text": "Put a washer on the outside of the banjo only.", "correct": false}, {"id": "b", "text": "Put a washer on the inside of the banjo only.", "correct": false}, {"id": "c", "text": "Put washer either side of the banjo.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A 0.5 in. diameter pipe is to be joined using standard nuts and fittings. What coupling would you use?', '[{"id": "a", "text": "AN8-8852-1.", "correct": false}, {"id": "b", "text": "AN8-8852-2.", "correct": false}, {"id": "c", "text": "AN8-8852-8.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'To install a flareless coupling', '[{"id": "a", "text": "turn until torque is felt plus 3 flats (half turn).", "correct": false}, {"id": "b", "text": "hand tight plus 2 flats.", "correct": false}, {"id": "c", "text": "turn until torque is felt plus 2 flats.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A Skydrol hydraulic seal would be made of', '[{"id": "a", "text": "butyl rubber, ethylene propylene or Teflon (phosphate ester compatible).", "correct": true}, {"id": "b", "text": "natural rubber, vegetable based.", "correct": false}, {"id": "c", "text": "synthetic rubber, mineral based.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Adapter nipples are not required on [see note]', '[{"id": "a", "text": "pipe to externally coned adapter.", "correct": true}, {"id": "b", "text": "pipe to pipe coupling.", "correct": false}, {"id": "c", "text": "pipe to internally coned adapter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A butyl rubber seal is made from', '[{"id": "a", "text": "silicon rubber.", "correct": false}, {"id": "b", "text": "synthetic rubber.", "correct": true}, {"id": "c", "text": "latex natural rubber.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the colour of an AN steel flared-tube fitting?', '[{"id": "a", "text": "Black.", "correct": true}, {"id": "b", "text": "Red.", "correct": false}, {"id": "c", "text": "Blue.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which statement about Military Standard (MS) flareless fittings is correct? During installation, MS flareless fittings are normally tightened by turning the nut a specified amount after', '[{"id": "a", "text": "the sleeve and fitting sealing surface have made contact, rather than being torqued.", "correct": true}, {"id": "b", "text": "MS flareless fittings must be tightened to a specific torque.", "correct": false}, {"id": "c", "text": "MS flareless fittings should not be lubricated prior to assembly.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A flexible sealing element subject to motion is a', '[{"id": "a", "text": "gasket.", "correct": false}, {"id": "b", "text": "packing.", "correct": true}, {"id": "c", "text": "compound.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Coil springs are made from', '[{"id": "a", "text": "carbon or alloy steels with high working stress.", "correct": true}, {"id": "b", "text": "low carbon steels with high working stress.", "correct": false}, {"id": "c", "text": "carbon or high alloy steels with low working stress.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What load are spring hooks subjected to?', '[{"id": "a", "text": "Bending.", "correct": true}, {"id": "b", "text": "Tension.", "correct": false}, {"id": "c", "text": "Compressive.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Steel music wire is', '[{"id": "a", "text": "used for lower strength springs.", "correct": false}, {"id": "b", "text": "made of high carbon or nickel alloy.", "correct": false}, {"id": "c", "text": "used for high strength springs and as progressive-rate springs.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A spring should be inspected for correct', '[{"id": "a", "text": "length, strength and squareness.", "correct": true}, {"id": "b", "text": "width, strength and squareness.", "correct": false}, {"id": "c", "text": "width, length and strength.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Needle roller bearings', '[{"id": "a", "text": "can accept a small amount of misalignment.", "correct": false}, {"id": "b", "text": "are susceptible to brinelling.", "correct": true}, {"id": "c", "text": "are designed to carry axial loads.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When rotating a ball bearing by hand, a regular click indicates', '[{"id": "a", "text": "a cracked ring.", "correct": true}, {"id": "b", "text": "damage to the balls.", "correct": false}, {"id": "c", "text": "intergranular corrosion in the outer ring.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A journal load is', '[{"id": "a", "text": "compression.", "correct": false}, {"id": "b", "text": "radial.", "correct": true}, {"id": "c", "text": "axial.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What kind of bearing is used in a landing system?', '[{"id": "a", "text": "Needle roller bearing.", "correct": false}, {"id": "b", "text": "Tapered roller bearing.", "correct": true}, {"id": "c", "text": "Caged ball bearing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What kind of bearing is used in a landing system?', '[{"id": "a", "text": "Needle roller bearing.", "correct": false}, {"id": "b", "text": "Tapered roller bearing.", "correct": true}, {"id": "c", "text": "Caged ball bearing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Spherical roller bearings resist what loads?', '[{"id": "a", "text": "Large radial but no thrust.", "correct": false}, {"id": "b", "text": "Large radial and moderate thrust.", "correct": true}, {"id": "c", "text": "Large thrust and moderate radial.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Where are needle roller bearings used?', '[{"id": "a", "text": "High speed operations.", "correct": false}, {"id": "b", "text": "Where is fluid damped bearing used.", "correct": false}, {"id": "c", "text": "Where there are space restrictions.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Loads on tapered roller bearings are', '[{"id": "a", "text": "thrust only.", "correct": false}, {"id": "b", "text": "radial only.", "correct": false}, {"id": "c", "text": "radial and thrust.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A Hardy Spicer coupling has what type of bearings?', '[{"id": "a", "text": "Ball Bearings.", "correct": false}, {"id": "b", "text": "Needle bearings.", "correct": true}, {"id": "c", "text": "Plain bearings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A self aligning bearing is a', '[{"id": "a", "text": "angular bearing.", "correct": false}, {"id": "b", "text": "precision bearing.", "correct": false}, {"id": "c", "text": "radial bearing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A crankshaft would be fitted with a', '[{"id": "a", "text": "cylindrical roller bearing.", "correct": true}, {"id": "b", "text": "taper roller bearing.", "correct": false}, {"id": "c", "text": "spherical roller bearing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Where heat is likely to be transmitted through a bearing', '[{"id": "a", "text": "group 2 bearings are used.", "correct": false}, {"id": "b", "text": "group 4 bearings are used.", "correct": false}, {"id": "c", "text": "group 3 bearings are used.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Shielded ball bearings are inspected by', '[{"id": "a", "text": "running at operating speed and listening for signs of wear.", "correct": false}, {"id": "b", "text": "dismantling and inspecting.", "correct": false}, {"id": "c", "text": "rotating slowly by hand.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Thrust bearings take', '[{"id": "a", "text": "radial loads.", "correct": false}, {"id": "b", "text": "journal loads.", "correct": false}, {"id": "c", "text": "sideloads.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A single row ball bearing is best suited to accepting', '[{"id": "a", "text": "radial loads only.", "correct": false}, {"id": "b", "text": "axial loads only.", "correct": false}, {"id": "c", "text": "axial and radial loads.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Taper roller bearings are used for which of the following purposes?', '[{"id": "a", "text": "To transmit radial loads whilst resisting axial movement.", "correct": false}, {"id": "b", "text": "To transmit thrust loads with radial loads.", "correct": true}, {"id": "c", "text": "To permit axial movement whilst resisting radial load.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The stationary race of a journal bearing is normally', '[{"id": "a", "text": "a spigoted fit.", "correct": false}, {"id": "b", "text": "an interference fit.", "correct": false}, {"id": "c", "text": "a push fit.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Inspection of bearings is normally carried out [see note]', '[{"id": "a", "text": "in situ.", "correct": true}, {"id": "b", "text": "when dismantled.", "correct": false}, {"id": "c", "text": "when removed from an assembly.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Damage to the shield of a bearing should result in', '[{"id": "a", "text": "no action.", "correct": false}, {"id": "b", "text": "replacement of the shield.", "correct": false}, {"id": "c", "text": "rejection of the bearing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A watermark on a bearing indicates [see note]', '[{"id": "a", "text": "bearing running dry.", "correct": true}, {"id": "b", "text": "intergranular corrosion.", "correct": false}, {"id": "c", "text": "lack of lubrication.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Needle bearings resist', '[{"id": "a", "text": "radial and axial load.", "correct": false}, {"id": "b", "text": "axial load only.", "correct": false}, {"id": "c", "text": "radial load only.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When silica gel has absorbed moisture the colour changes to', '[{"id": "a", "text": "pink.", "correct": true}, {"id": "b", "text": "white.", "correct": false}, {"id": "c", "text": "blue.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A thrust bearing is designed so that', '[{"id": "a", "text": "it transmits radial loads, therefore limiting axial movement.", "correct": false}, {"id": "b", "text": "it transmits axial loads, therefore limiting radial movement.", "correct": false}, {"id": "c", "text": "it transmits axial loads, therefore limiting axial movement.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Lubrication of roller bearings and needle bearings are', '[{"id": "a", "text": "at low pressure via a tube.", "correct": false}, {"id": "b", "text": "under pressure.", "correct": true}, {"id": "c", "text": "by hand.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Silica gel is used for moisture control during storage, when serviceable it is coloured', '[{"id": "a", "text": "blue.", "correct": true}, {"id": "b", "text": "white.", "correct": false}, {"id": "c", "text": "pink.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How do you check a chain for elongation?', '[{"id": "a", "text": "Apply a load, measure chain and use 5% max formula to check extension.", "correct": false}, {"id": "b", "text": "Apply a load, measure chain and use 2% max formula to check extension.", "correct": true}, {"id": "c", "text": "Hang the chain under its own weight, measure chain and use 2% max formula to check extension.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How do you store a chain?', '[{"id": "a", "text": "Oiled and coiled in greaseproof paper.", "correct": true}, {"id": "b", "text": "Lay uncoiled and flat in greaseproof paper.", "correct": false}, {"id": "c", "text": "Hanged so they do not kink.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Epicyclic gears are used on', '[{"id": "a", "text": "shafts rotating on axis 90 degrees from each other.", "correct": false}, {"id": "b", "text": "shafts rotating on the same axis.", "correct": true}, {"id": "c", "text": "shafts rotating on offset axis.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the purpose of the guard, where a control chain goes around a sprocket?', '[{"id": "a", "text": "Stops the chain coming off if it goes slack.", "correct": true}, {"id": "b", "text": "Protects personnel when carrying out maintenance.", "correct": false}, {"id": "c", "text": "Prevents entry of foreign bodies.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Worm drives operate in shafts which are', '[{"id": "a", "text": "90 degrees to each other and in a differing plane.", "correct": true}, {"id": "b", "text": "90 degrees to each other and in the same plane.", "correct": false}, {"id": "c", "text": "parallel to each other and in the same plane.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The pattern of a gear is the', '[{"id": "a", "text": "the path they take when the gear is rotating.", "correct": false}, {"id": "b", "text": "profile of the gear teeth.", "correct": false}, {"id": "c", "text": "mark it leaves on a mating gear.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How is the change in direction of a control chain, in two planes, achieved?', '[{"id": "a", "text": "By using a pulley.", "correct": false}, {"id": "b", "text": "By using bi-planer blocks.", "correct": true}, {"id": "c", "text": "By using spring clips.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How is a non-reversible chain different from a normal chain?', '[{"id": "a", "text": "By use of a chain guard.", "correct": false}, {"id": "b", "text": "Every second outer plate is extended in one direction.", "correct": true}, {"id": "c", "text": "Different end fittings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When not under load where should a pair of gears sit?', '[{"id": "a", "text": "In the middle.", "correct": false}, {"id": "b", "text": "On the toe.", "correct": true}, {"id": "c", "text": "On the heel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'For a pair of gears to operate properly, they must have', '[{"id": "a", "text": "lash and pattern.", "correct": true}, {"id": "b", "text": "end play and thrust.", "correct": false}, {"id": "c", "text": "pattern and profile.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The teeth on the smaller wheel of a bevel gear are called the', '[{"id": "a", "text": "heel.", "correct": false}, {"id": "b", "text": "toe.", "correct": true}, {"id": "c", "text": "foot.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The correct meshing of gears is found by observing the marks made during a gear mesh test. On what part of the tooth should the marks be?', '[{"id": "a", "text": "Top.", "correct": false}, {"id": "b", "text": "Bottom.", "correct": false}, {"id": "c", "text": "Middle.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What type of gear would be used on a propeller reduction gearbox?', '[{"id": "a", "text": "Split epicyclic.", "correct": false}, {"id": "b", "text": "Bevel.", "correct": false}, {"id": "c", "text": "Epicyclic.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Where would you find the inspection interval for chains?', '[{"id": "a", "text": "Overhaul manual.", "correct": false}, {"id": "b", "text": "Maintenance schedule.", "correct": true}, {"id": "c", "text": "Maintenance manual.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A feather key locates a gear on a shaft and permits', '[{"id": "a", "text": "positive drive and axial movement.", "correct": true}, {"id": "b", "text": "positive drive with the gear firmly locked.", "correct": false}, {"id": "c", "text": "a positive and strong drive for transmissions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A worm drive creates', '[{"id": "a", "text": "a drive in 2 planes and transmits both directions.", "correct": false}, {"id": "b", "text": "a drive in 1 plane but transmits both directions.", "correct": false}, {"id": "c", "text": "a drive in 2 planes but transmits 1 direction only.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The teeth of a gear would normally be', '[{"id": "a", "text": "nitrided.", "correct": false}, {"id": "b", "text": "tempered.", "correct": false}, {"id": "c", "text": "case hardened.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'If a chain is removed for routine maintenance', '[{"id": "a", "text": "it must be proof checked to full load.", "correct": false}, {"id": "b", "text": "it must be proof checked to ½ max load.", "correct": false}, {"id": "c", "text": "it does not have to be proof checked.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'On gear teeth, the wear pattern should be', '[{"id": "a", "text": "the middle of the tooth most worn.", "correct": false}, {"id": "b", "text": "even from top to bottom.", "correct": true}, {"id": "c", "text": "the top edge most worn.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'On bevel gear teeth, the wear pattern should be', '[{"id": "a", "text": "at the centre of the tooth.", "correct": true}, {"id": "b", "text": "greatest at the heel, least at the toe.", "correct": false}, {"id": "c", "text": "greatest at the toe, tapering off to the heel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Bevel gears are', '[{"id": "a", "text": "all over case hardened.", "correct": true}, {"id": "b", "text": "heel is hardened.", "correct": false}, {"id": "c", "text": "toe is hardened.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A chain is checked for stiff links by', '[{"id": "a", "text": "hanging by hand by measure and sight.", "correct": false}, {"id": "b", "text": "stretching out and measuring.", "correct": false}, {"id": "c", "text": "running the chain over a finger by 180 degrees.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'During an inspection interval one segment of a long chain is found to be defective, the solution to this is to', '[{"id": "a", "text": "replace 3 segment either side of the deficiency.", "correct": false}, {"id": "b", "text": "replace the whole chain.", "correct": true}, {"id": "c", "text": "replace the particular segment and run components to check for serviceability.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The teeth of a gear would normally be', '[{"id": "a", "text": "tempered.", "correct": false}, {"id": "b", "text": "case hardened.", "correct": true}, {"id": "c", "text": "nitrided.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Non-reversible chains can', '[{"id": "a", "text": "only be moved in one direction.", "correct": false}, {"id": "b", "text": "only be fitted in one direction.", "correct": true}, {"id": "c", "text": "not be fitted through pressure bulkheads.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The large diameter on a bevel gear is called the', '[{"id": "a", "text": "foot.", "correct": false}, {"id": "b", "text": "toe.", "correct": false}, {"id": "c", "text": "heel.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How do you check a chain for elongation?', '[{"id": "a", "text": "Lay flat on a table, apply tensile load and measure.", "correct": false}, {"id": "b", "text": "Adjust the end fittings.", "correct": false}, {"id": "c", "text": "Hang chain up, check sight line and measure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Drive planes on an epicyclic gear are', '[{"id": "a", "text": "around a common axis of the plane.", "correct": true}, {"id": "b", "text": "at different angles to the plane.", "correct": false}, {"id": "c", "text": "at right angles to the plane.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Compared with the spur gears, spiral gears have', '[{"id": "a", "text": "have mechanical advantages.", "correct": false}, {"id": "b", "text": "less stress concentration on gears.", "correct": true}, {"id": "c", "text": "more wear resistance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The clutch which can overrun the driving member is known as', '[{"id": "a", "text": "an overload clutch.", "correct": false}, {"id": "b", "text": "a no-slip clutch.", "correct": false}, {"id": "c", "text": "a freewheel clutch.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A gear system, or gear train, is made up of gears that are', '[{"id": "a", "text": "driven and driver.", "correct": false}, {"id": "b", "text": "idler.", "correct": false}, {"id": "c", "text": "driven, driver and idler.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When is a turnbuckle not in safety?', '[{"id": "a", "text": "When a small diameter wire can be passed through the inspection hole.", "correct": false}, {"id": "b", "text": "When you can see daylight through the hole.", "correct": false}, {"id": "c", "text": "When a wire of the same diameter as the inspection hole can be passed through.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How do you check a turnbuckle is in safety?', '[{"id": "a", "text": "Use the inspection hole or count the threads showing.", "correct": true}, {"id": "b", "text": "Ensure that the turnbuckle cannot be turned by hand.", "correct": false}, {"id": "c", "text": "Make sure no threads are showing at either end of the turnbuckle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'British aircraft cables are classified by their', '[{"id": "a", "text": "breaking load in hundredweights.", "correct": true}, {"id": "b", "text": "breaking loads in lbf, where 1 lbf = 4.448N.", "correct": false}, {"id": "c", "text": "diameter and breaking load in Hundredweights.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Cables are preferred to other control systems because', '[{"id": "a", "text": "single braid allows for 2 way directions.", "correct": false}, {"id": "b", "text": "they are strong and light.", "correct": true}, {"id": "c", "text": "they maintain slight mechanical advantage over push/pull systems.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Turnbuckles, depending on type, are locked by', '[{"id": "a", "text": "stiffnuts.", "correct": false}, {"id": "b", "text": "locknuts and wire.", "correct": true}, {"id": "c", "text": "castleated nuts and splitpins.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Cable tension is maintained by', '[{"id": "a", "text": "a grommet.", "correct": false}, {"id": "b", "text": "a cable tension regulator.", "correct": true}, {"id": "c", "text": "a fairlead.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'To correctly tension cables it can help to', '[{"id": "a", "text": "take up initial slack by additional pulleys.", "correct": false}, {"id": "b", "text": "have control surface locks in to support weight and adjust turnbuckles equally.", "correct": true}, {"id": "c", "text": "use a cable run with turnbuckles at least every eight feet.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'British turnbuckles are checked for safety by', '[{"id": "a", "text": "attempting to pass a hardened pin probe through the inspection hole.", "correct": false}, {"id": "b", "text": "attempting to pass locking wire through the hole.", "correct": true}, {"id": "c", "text": "looking through the hole and checking for threads showing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Turnbuckles are correctly fitted when', '[{"id": "a", "text": "both rods are seen to touch in the inspection hole.", "correct": false}, {"id": "b", "text": "both rods enter the barrel by the same amount.", "correct": false}, {"id": "c", "text": "the inspection hole is blind or the required number of threads are showing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How is the diameter of a cable measured?', '[{"id": "a", "text": "Diameter of one wire multiplied by the number of wires.", "correct": false}, {"id": "b", "text": "Overall diameter.", "correct": true}, {"id": "c", "text": "Diameter of one wire only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), '9 * 16 cable is', '[{"id": "a", "text": "9 strands of 16 wires.", "correct": true}, {"id": "b", "text": "9 cables having 16 turns per inch.", "correct": false}, {"id": "c", "text": "cable size 9/16 inch diameter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Turnbuckles are used to', '[{"id": "a", "text": "join the two ends of the cable.", "correct": false}, {"id": "b", "text": "adjust major tension on the cable.", "correct": false}, {"id": "c", "text": "adjust minor tension on the cable.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Spring locking clips for turnbuckles can be used on', '[{"id": "a", "text": "no flying control cables.", "correct": false}, {"id": "b", "text": "all flying control cables.", "correct": true}, {"id": "c", "text": "only on trim control cables.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the small hole on a swaged turnbuckle for?', '[{"id": "a", "text": "To check for moisture deposits.", "correct": false}, {"id": "b", "text": "To check if correct amount of cable has been inserted before swaging.", "correct": true}, {"id": "c", "text": "To alloy the turnbuckle to be wire locked.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When checking the safety of turnbuckles you should use what?', '[{"id": "a", "text": "Visual check.", "correct": false}, {"id": "b", "text": "Wire the same diameter as the inspection hole.", "correct": true}, {"id": "c", "text": "Wire smaller than inspection hole.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Cable minimum breakage strain for British and American is measured by', '[{"id": "a", "text": "hundredweight for British, c.s.a. and pounds for American.", "correct": true}, {"id": "b", "text": "hundredweight for British, c.s.a. hundredweight for American.", "correct": false}, {"id": "c", "text": "pounds for both.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'If a pulley shows signs of wear on one side', '[{"id": "a", "text": "the cable is too tightly tensed.", "correct": false}, {"id": "b", "text": "the pulley is too large for the cable.", "correct": false}, {"id": "c", "text": "the cable is misaligned.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A 7x7 cable has seven strands each of', '[{"id": "a", "text": "fourteen wires.", "correct": false}, {"id": "b", "text": "seven wires.", "correct": true}, {"id": "c", "text": "one wire.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Cable stops are manufactured from', '[{"id": "a", "text": "stainless steel.", "correct": false}, {"id": "b", "text": "copper.", "correct": true}, {"id": "c", "text": "magnesium alloy.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Pulleys are manufactured from', '[{"id": "a", "text": "brass and phenolic resin.", "correct": true}, {"id": "b", "text": "tungum and high tensile steel.", "correct": false}, {"id": "c", "text": "stainless steel and nylon.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A cable tension regulator will be installed in a flying control system to', '[{"id": "a", "text": "automatically compensate for low cable tension caused by worn cables.", "correct": false}, {"id": "b", "text": "compensate for rapid movement of the controls by taking up the slack.", "correct": false}, {"id": "c", "text": "allow for variations in temperature which will vary the cable tension.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Aircraft flying control cables are normally classified by the', '[{"id": "a", "text": "circumference of the cable and overall length.", "correct": false}, {"id": "b", "text": "number of strands it contains and the number of wires in each strand.", "correct": false}, {"id": "c", "text": "minimum breaking load or the diameter in inches.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), '7 * 7 cable has seven stranded wires each with', '[{"id": "a", "text": "7 wires.", "correct": true}, {"id": "b", "text": "14 wires.", "correct": false}, {"id": "c", "text": "49 wires.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Tension regulators on aeroplanes with fully metal bodies are used to', '[{"id": "a", "text": "set up the necessary tension.", "correct": false}, {"id": "b", "text": "maintain the necessary tension.", "correct": true}, {"id": "c", "text": "relax the tension in cold conditions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the smallest size cable that may be used in aircraft primary control systems?', '[{"id": "a", "text": "5/16 inch.", "correct": false}, {"id": "b", "text": "1/4 inch.", "correct": false}, {"id": "c", "text": "1/8 inch.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How are changes in direction of a control cable accomplished?', '[{"id": "a", "text": "Bellcranks.", "correct": false}, {"id": "b", "text": "Fairleads.", "correct": false}, {"id": "c", "text": "Pulleys.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A flight control cable is replaced if', '[{"id": "a", "text": "individual wires are broken.", "correct": true}, {"id": "b", "text": "the protective fluid coating is missing.", "correct": false}, {"id": "c", "text": "a wire is 20% worn.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A 14 gauge cable when compared to an 18 gauge cable has', '[{"id": "a", "text": "the same current rating.", "correct": false}, {"id": "b", "text": "higher current rating.", "correct": true}, {"id": "c", "text": "lower current rating.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In a front release connector, the pin will be', '[{"id": "a", "text": "released from the front and extracted from the rear.", "correct": true}, {"id": "b", "text": "released from rear and extracted from the front.", "correct": false}, {"id": "c", "text": "released from the front and extracted from the front.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'An interconnect cable has what insulation?', '[{"id": "a", "text": "same thickness as airframe cable.", "correct": false}, {"id": "b", "text": "thicker than airframe cable.", "correct": false}, {"id": "c", "text": "thinner than airframe cable.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Why is the ground side of an electrical power conductor usually connected to a male connector?', '[{"id": "a", "text": "To make installation of the connector easier.", "correct": false}, {"id": "b", "text": "To reduce the chance of an accidental short.", "correct": true}, {"id": "c", "text": "To reduce the chance of corrosion affecting the pins.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Maximum temperature of tin coated copper cable is', '[{"id": "a", "text": "200 °C.", "correct": false}, {"id": "b", "text": "260 °C.", "correct": false}, {"id": "c", "text": "105 °C.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Plug pins are numbered', '[{"id": "a", "text": "from the outside in - clockwise.", "correct": false}, {"id": "b", "text": "from the inside out - clockwise.", "correct": true}, {"id": "c", "text": "from the inside out - anticlockwise.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Equipment wire', '[{"id": "a", "text": "is flexible and suitable for soldering.", "correct": true}, {"id": "b", "text": "can be used for interconnect wiring.", "correct": false}, {"id": "c", "text": "has thicker insulation than interconnect wire.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In the wiring code 1EF6B22 NMS V, what does the number 6 (the fourth character from the left) represent?', '[{"id": "a", "text": "Cable number.", "correct": true}, {"id": "b", "text": "Circuit function.", "correct": false}, {"id": "c", "text": "Cable size.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'An aluminium oxide layer on a conductor will do what when the temperature is increased?', '[{"id": "a", "text": "Remain the same.", "correct": false}, {"id": "b", "text": "Become thicker.", "correct": true}, {"id": "c", "text": "Become thinner.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is a coaxial cable?', '[{"id": "a", "text": "A single conductor.", "correct": false}, {"id": "b", "text": "Two or more conductors.", "correct": true}, {"id": "c", "text": "A twisted pair of conductors.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What must you be careful with a hot stamped cable? [see note]', '[{"id": "a", "text": "Corrosion.", "correct": false}, {"id": "b", "text": "Peeling of the insulation.", "correct": false}, {"id": "c", "text": "Wet arc tracking.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the effect of aluminium oxide on aluminium electrical cable?', '[{"id": "a", "text": "Insulates.", "correct": true}, {"id": "b", "text": "Reduces resistance.", "correct": false}, {"id": "c", "text": "Provides strength.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What amperage is an 18 SWG cable?', '[{"id": "a", "text": "1 amp.", "correct": false}, {"id": "b", "text": "10 amp.", "correct": true}, {"id": "c", "text": "5 amp.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A co-axial cable is better than a normal cable because', '[{"id": "a", "text": "there is an electrostatic field around it which helps to reduce the electromagnetic field.", "correct": true}, {"id": "b", "text": "weight for weight it can carry more signal.", "correct": false}, {"id": "c", "text": "it has less resistance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'What is the danger if a silver coated connector comes into contact with glycol de-icing fluid', '[{"id": "a", "text": "Fire hazard.", "correct": true}, {"id": "b", "text": "Corrosion.", "correct": false}, {"id": "c", "text": "Wet arc tracking.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When silver coated connectors are used in unpressurised parts of the aircraft', '[{"id": "a", "text": "wet track arcing can occur.", "correct": true}, {"id": "b", "text": "separation of the coating can occur.", "correct": false}, {"id": "c", "text": "corrosion can occur.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The conductor in Tersil cable is', '[{"id": "a", "text": "stainless steel.", "correct": false}, {"id": "b", "text": "nickel plated copper.", "correct": true}, {"id": "c", "text": "tinned copper.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A cable is marked NYVIN 22. The 22 represents the', '[{"id": "a", "text": "current/weight ratio.", "correct": false}, {"id": "b", "text": "cross sectional area.", "correct": false}, {"id": "c", "text": "current rating.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Copper is an inferior conductor to aluminium when comparing', '[{"id": "a", "text": "weight for weight.", "correct": true}, {"id": "b", "text": "CSA with CSA.", "correct": false}, {"id": "c", "text": "load for load.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Silver plated copper wire has a maximum working temp of', '[{"id": "a", "text": "250 °C.", "correct": false}, {"id": "b", "text": "300 °C.", "correct": false}, {"id": "c", "text": "200 °C.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'For an electrical cable to be fireproof it must be able to stand 1100 °C for [see note]', '[{"id": "a", "text": "20 mins.", "correct": false}, {"id": "b", "text": "10 mins.", "correct": false}, {"id": "c", "text": "15 mins.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Oxide on exposed silver plated wires is', '[{"id": "a", "text": "non corrosive.", "correct": false}, {"id": "b", "text": "a conductor.", "correct": true}, {"id": "c", "text": "an insulator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'On a rear insert plug the tool is used to', '[{"id": "a", "text": "insert the pins from the front and extracted from the rear.", "correct": false}, {"id": "b", "text": "insert the pins from the rear and extract from the front.", "correct": false}, {"id": "c", "text": "insert the pins from the rear and extract from the rear.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Nickel coated cables temperature range is', '[{"id": "a", "text": "200 to 250 °C.", "correct": true}, {"id": "b", "text": "150 to 200 °C.", "correct": false}, {"id": "c", "text": "100 to 150 °C.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Aluminium wiring when flexed will', '[{"id": "a", "text": "have a higher resistance.", "correct": false}, {"id": "b", "text": "have no effect.", "correct": false}, {"id": "c", "text": "work harden and embrittle.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A foot operated hydraulic swaging tool is checked for fluid level', '[{"id": "a", "text": "vertically.", "correct": true}, {"id": "b", "text": "horizontally.", "correct": false}, {"id": "c", "text": "only when operating pressure is reached.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'On a hydraulic swaging tool, the swage is formed when', '[{"id": "a", "text": "the bypass valve closes and ram is neutrally loaded.", "correct": false}, {"id": "b", "text": "the bypass valve opens and ram is neutrally loaded.", "correct": true}, {"id": "c", "text": "swage pressure is reached on the gauge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Interference in ribbon cables can be prevented by', '[{"id": "a", "text": "the use of a common earth return between signal wires in the cable.", "correct": false}, {"id": "b", "text": "grounding alternate wires so that signal wires are never adjacent.", "correct": true}, {"id": "c", "text": "using alternate return wires so that the cable differences cancel each other out.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'H.T. leads are', '[{"id": "a", "text": "multi-strand, single-core, screened.", "correct": true}, {"id": "b", "text": "single-strand, single-core, screened.", "correct": false}, {"id": "c", "text": "multi-strand, multi-core, screened.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'If the cross sectional area of a cable is increased, what will happen to the voltage drop?', '[{"id": "a", "text": "Decrease.", "correct": true}, {"id": "b", "text": "Increase.", "correct": false}, {"id": "c", "text": "Stay the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The cross sectional area of a copper crimp barrel is', '[{"id": "a", "text": "larger than an aluminium one.", "correct": false}, {"id": "b", "text": "smaller than an aluminium one.", "correct": true}, {"id": "c", "text": "same as an aluminium one.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Electrical cable on aircraft is mainly made from copper because', '[{"id": "a", "text": "it offers low resistance to current flow.", "correct": true}, {"id": "b", "text": "it more malleable.", "correct": false}, {"id": "c", "text": "it does not oxidise.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When crimping, what chapter in the ATA system should you refer to?', '[{"id": "a", "text": "20.", "correct": true}, {"id": "b", "text": "24.", "correct": false}, {"id": "c", "text": "12.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Interconnect cables', '[{"id": "a", "text": "employ thinner insulation than airframe types.", "correct": true}, {"id": "b", "text": "are used for equipment wire in the unified system.", "correct": false}, {"id": "c", "text": "are the cable through the MEC to the engine.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The first step for the coaxial cable to attach to the end fitting is', '[{"id": "a", "text": "use a tooling hold between the assembly and cable.", "correct": false}, {"id": "b", "text": "the outer covering is cut back to expose the braided outer conductors.", "correct": true}, {"id": "c", "text": "back-off the insulator and connect with conductor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A fire resistant cable must maintain adequate insulation in a fire for', '[{"id": "a", "text": "10 minutes.", "correct": false}, {"id": "b", "text": "5 minutes.", "correct": true}, {"id": "c", "text": "30 minutes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When silver coated connectors are used in unpressurised parts of the aircraft', '[{"id": "a", "text": "wet track arcing can occur.", "correct": true}, {"id": "b", "text": "red plague can occur.", "correct": false}, {"id": "c", "text": "separation of the coating can occur.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Knuckling is a problem on earlier aircraft cables due to', '[{"id": "a", "text": "hot stamping of cables.", "correct": true}, {"id": "b", "text": "too much flux.", "correct": false}, {"id": "c", "text": "wires being pulled through too hard.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Which of the following types of electrical wire is likely to be used for connection of thermo- couples around the jet-pipe of a turbine engine?', '[{"id": "a", "text": "Nyvin.", "correct": false}, {"id": "b", "text": "Tersil.", "correct": false}, {"id": "c", "text": "Fepsil.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The main reason why crimped joints are preferable to soldered joints is', '[{"id": "a", "text": "the quality of crimped joints will be constant.", "correct": true}, {"id": "b", "text": "no flux is needed.", "correct": false}, {"id": "c", "text": "there is no heat required.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The main reason why crimped joints are preferable to soldered joints is', '[{"id": "a", "text": "the quality of crimped joints will be constant.", "correct": true}, {"id": "b", "text": "no flux is needed.", "correct": false}, {"id": "c", "text": "there is no heat required.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Crimping terminals are colour coded. The colour indicates', '[{"id": "a", "text": "the type of crimping tool to be used only.", "correct": false}, {"id": "b", "text": "the wire size to be used with that crimp only.", "correct": false}, {"id": "c", "text": "both the crimping tool and the size of the wire to be used.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'A 14 SWG electrical cable when compared with an 18 SWG cable can carry', '[{"id": "a", "text": "less current.", "correct": false}, {"id": "b", "text": "the same current.", "correct": false}, {"id": "c", "text": "more current.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Co-axial cables are used', '[{"id": "a", "text": "as they are able to handle high current.", "correct": false}, {"id": "b", "text": "as the fields due to current flow in the inner and outer cancel each other out.", "correct": false}, {"id": "c", "text": "as they are protected from electromagnetic interference.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Direct removal connector pins are', '[{"id": "a", "text": "fitted from the front but removed from the rear.", "correct": false}, {"id": "b", "text": "fitted from the rear and removed from the rear.", "correct": true}, {"id": "c", "text": "fitted from the rear and removed from the front.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When installing coaxial cable, it should be secured along its entire length', '[{"id": "a", "text": "at 2-foot intervals.", "correct": true}, {"id": "b", "text": "at 1-foot intervals.", "correct": false}, {"id": "c", "text": "wherever the cable sags.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How should splices be arranged if several are to be located in an electrical wire bundle?', '[{"id": "a", "text": "Enclosed in a conduit.", "correct": false}, {"id": "b", "text": "Grouped together to facilitate inspection.", "correct": false}, {"id": "c", "text": "Staggered along the length of the cable.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When approved, splices may be used to repair manufactured harnesses of installed wiring. The maximum number of splices permitted between any two connectors is', '[{"id": "a", "text": "two.", "correct": false}, {"id": "b", "text": "one.", "correct": true}, {"id": "c", "text": "three.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The most common method of attaching a pin or socket to an individual wire in an MS electrical connector is by', '[{"id": "a", "text": "crimping.", "correct": true}, {"id": "b", "text": "soldering.", "correct": false}, {"id": "c", "text": "crimping and soldering.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The pin section of an AN/MS connector is normally installed on', '[{"id": "a", "text": "the power supply side of the circuit.", "correct": false}, {"id": "b", "text": "either side of a circuit (makes no difference).", "correct": false}, {"id": "c", "text": "the ground side of the circuit.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The primary considerations when selecting electric cable size are', '[{"id": "a", "text": "the voltage and amperage of the load it must carry.", "correct": false}, {"id": "b", "text": "the system voltage and cable length.", "correct": false}, {"id": "c", "text": "current-carrying capacity and allowable voltage drop.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'How does the routing of coaxial cables differ from the routing of electrical wires?', '[{"id": "a", "text": "Coaxial cables are routed at right angles to stringers and ribs.", "correct": false}, {"id": "b", "text": "Coaxial cables are routed as directly as possible.", "correct": true}, {"id": "c", "text": "Coaxial cables are routed parallel with stringers and ribs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The socket section of an AN/MS connector is normally installed on', '[{"id": "a", "text": "the power supply side of the circuit.", "correct": true}, {"id": "b", "text": "the ground side of the circuit.", "correct": false}, {"id": "c", "text": "either side of a circuit (makes no difference).", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'In the American Wire Gauge (AWG) system of numbers used to designate electrical wire sizes, the number assigned to a size is related to its', '[{"id": "a", "text": "cross sectional area.", "correct": true}, {"id": "b", "text": "combined resistance and current-carrying capacity.", "correct": false}, {"id": "c", "text": "current-carrying capacity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Where electrical cables pass through holes in bulkheads, formers, ribs, firewalls etc., the wires should be protected from chafing by', '[{"id": "a", "text": "wrapping with electrical tape.", "correct": false}, {"id": "b", "text": "wrapping with plastic.", "correct": false}, {"id": "c", "text": "using a suitable grommet.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When carbon is fully dissolved in iron and therefore uniformly distributed in solid solution, the metallurgical structure is called.', '[{"id": "a", "text": "Ferrite.", "correct": false}, {"id": "b", "text": "Austenite.", "correct": true}, {"id": "c", "text": "Pearlite.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When one carbon atom chemically combines with 3 iron atoms, the result is called', '[{"id": "a", "text": "Martensite.", "correct": false}, {"id": "b", "text": "Pearlite.", "correct": false}, {"id": "c", "text": "Cementite or Iron Carbide.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Cementite laminated with ferrite in alternate layers produces', '[{"id": "a", "text": "Ferrite/Iron.", "correct": false}, {"id": "b", "text": "Pearlite.", "correct": true}, {"id": "c", "text": "Martensite.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Pearlite combines the properties of', '[{"id": "a", "text": "martensite and iron carbide.", "correct": false}, {"id": "b", "text": "cementite and Martensite.", "correct": false}, {"id": "c", "text": "ferrite and cementite.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The amount of carbon necessary to produce a totally pearlitic structure is', '[{"id": "a", "text": "1.0%.", "correct": false}, {"id": "b", "text": "0.83%.", "correct": true}, {"id": "c", "text": "1.83%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The properties of ferritic metal are that it is both', '[{"id": "a", "text": "strong without being brittle.", "correct": false}, {"id": "b", "text": "strong but too hard and brittle.", "correct": false}, {"id": "c", "text": "soft and weak.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The properties of cementite metal are that it is both', '[{"id": "a", "text": "soft and weak.", "correct": false}, {"id": "b", "text": "strong but too hard and brittle.", "correct": true}, {"id": "c", "text": "strong without being brittle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'The properties of pearlitic metal are that it is both', '[{"id": "a", "text": "soft and weak.", "correct": false}, {"id": "b", "text": "strong without being brittle.", "correct": true}, {"id": "c", "text": "strong but too and hard and brittle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'When heating a straight carbon steel, there is a hesitation (slight pause) in the temperature rise before it increases a further 200oC. This hesitation is known as the', '[{"id": "a", "text": "Lower Critical Point.", "correct": true}, {"id": "b", "text": "Upper Critical Point.", "correct": false}, {"id": "c", "text": "Eutectic Point.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M06.12'), 'Referring to an iron/carbon phase diagram, when talking about the U.C.P. and L.C.P., the point where the two meet is known as the', '[{"id": "a", "text": "eutectoid point.", "correct": true}, {"id": "b", "text": "hesitation point.", "correct": false}, {"id": "c", "text": "point of no return.", "correct": false}]'::jsonb, '{B1,B2}');
